export const SUBJECT_PRACTICE_REVIEW_GATE_POLICY_VERSION = 'subject-practice-review-gate-v14-verified-basic-derivative-arithmetic-shape';
export const SUBJECT_PRACTICE_ZERO_PROVIDER_OBSERVATION_COST_POLICY_VERSION =
  'guarded-observation-zero-provider-cost-reservation-v1';

export function subjectPracticeObservationCostReservationValid(input: {
  route: 'local_deterministic_zero_provider' | 'provider_guarded';
  policyVersion?: unknown;
  maxEstimatedCostUsd?: unknown;
  storedMaximumReservedCostUsd?: unknown;
  currentMaximumReservedCostUsd?: unknown;
}) {
  const maximum = Number(input.maxEstimatedCostUsd);
  const stored = Number(input.storedMaximumReservedCostUsd);
  const current = Number(input.currentMaximumReservedCostUsd);
  if (![maximum, stored, current].every(Number.isFinite)) return false;
  if (input.route === 'local_deterministic_zero_provider') {
    return cleanString(input.policyVersion) === SUBJECT_PRACTICE_ZERO_PROVIDER_OBSERVATION_COST_POLICY_VERSION
      && maximum === 0
      && stored === 0
      && current === 0;
  }
  return cleanString(input.policyVersion) === 'guarded-observation-cost-reservation-v1'
    && maximum > 0
    && stored > 0
    && current > 0
    && stored <= maximum + Number.EPSILON
    && current <= maximum + Number.EPSILON;
}

export function subjectPracticeObservationGenerationJobCostReservationValid(input: {
  route?: unknown;
  policyVersion?: unknown;
  maxEstimatedCostUsd?: unknown;
  maximumReservedCostUsd?: unknown;
}) {
  const route = cleanString(input.route);
  if (route !== 'local_deterministic_zero_provider' && route !== 'provider_guarded') return false;
  return subjectPracticeObservationCostReservationValid({
    route,
    policyVersion: input.policyVersion,
    maxEstimatedCostUsd: input.maxEstimatedCostUsd,
    storedMaximumReservedCostUsd: input.maximumReservedCostUsd,
    currentMaximumReservedCostUsd: input.maximumReservedCostUsd
  });
}

export function subjectPracticeObservationRouteReadinessFor(input: {
  taskEnabled: boolean;
  executionEnabled: boolean;
  singletonConfirmed: boolean;
  observationOnlyMode: boolean;
  localGeneratorShadowEnabled: boolean;
  questionPlanEnabled: boolean;
  globalConcurrency: number;
  realtimeConcurrency: number;
  backgroundConcurrency: number;
  eligibleKeySlots: number;
}) {
  const commonReasons: string[] = [];
  if (!input.taskEnabled) commonReasons.push('observation_task_disabled');
  if (!input.executionEnabled) commonReasons.push('observation_execution_disabled');
  if (!input.singletonConfirmed) commonReasons.push('single_backend_not_confirmed');
  const providerReasons = [...commonReasons];
  if (input.backgroundConcurrency < 2) providerReasons.push('background_capacity_below_two');
  if (input.eligibleKeySlots < 2) providerReasons.push('eligible_background_key_slots_below_two');
  if (input.realtimeConcurrency + input.backgroundConcurrency > input.globalConcurrency) {
    providerReasons.push('child_capacity_exceeds_global_capacity');
  }
  const localZeroProviderReasons = [...commonReasons];
  if (!input.observationOnlyMode) localZeroProviderReasons.push('observation_only_mode_required');
  if (!input.localGeneratorShadowEnabled) localZeroProviderReasons.push('local_generator_shadow_disabled');
  if (!input.questionPlanEnabled) localZeroProviderReasons.push('question_plan_disabled');
  return {
    readyForSubmission: input.taskEnabled
      && providerReasons.filter((reason) => reason !== 'single_backend_not_confirmed').length === 0,
    readyForExecution: input.taskEnabled && input.executionEnabled && input.singletonConfirmed
      && providerReasons.length === 0,
    readyForLocalZeroProviderSubmission: input.taskEnabled
      && localZeroProviderReasons.filter((reason) => reason !== 'single_backend_not_confirmed').length === 0,
    readyForLocalZeroProviderExecution: input.taskEnabled && input.executionEnabled && input.singletonConfirmed
      && localZeroProviderReasons.length === 0,
    providerReasons,
    localZeroProviderReasons
  };
}

type SubjectPracticeAutomatedCandidateLeakageGateEvidence = {
  policyVersion: string;
  status: 'clear' | 'blocked' | 'ambiguous' | 'missing_corpus';
  scannedRevisionCount: number;
  blockedRevisionCount: number;
  ambiguousRevisionCount: number;
  reasonCodes: string[];
  revisionMatchSetSha256: string | null;
  revisionMatchDigestVersion: string;
  structuredCorpusSchemaVersion: string;
  normalizationVersion: string;
  sourceCorpusSnapshotSha256: string | null;
  sourceCorpusSnapshotVersion: string;
  sourceCorpusRevisionCount: number;
  sourceCorpusInventoryComplete: boolean;
  sourceCorpusInventoryMode: 'all_active_subject_source_questions_at_statement_snapshot';
  failClosed: true;
  sourceContentExposedToGenerator: false;
};

export function applySubjectPracticeAutomatedCandidateLeakageGate(
  review: ReviewResult,
  evidence: SubjectPracticeAutomatedCandidateLeakageGateEvidence | null
): ReviewResult {
  const completeClearEvidence = Boolean(evidence
    && evidence.status === 'clear'
    && evidence.scannedRevisionCount > 0
    && evidence.sourceCorpusRevisionCount === evidence.scannedRevisionCount
    && evidence.blockedRevisionCount === 0
    && evidence.ambiguousRevisionCount === 0
    && /^[a-f0-9]{64}$/.test(cleanString(evidence.revisionMatchSetSha256))
    && /^[a-f0-9]{64}$/.test(cleanString(evidence.sourceCorpusSnapshotSha256))
    && evidence.revisionMatchDigestVersion === SUBJECT_PRACTICE_CANDIDATE_NOVELTY_MATCH_DIGEST_VERSION
    && evidence.sourceCorpusSnapshotVersion === SUBJECT_PRACTICE_CANDIDATE_NOVELTY_CORPUS_SNAPSHOT_VERSION
    && evidence.structuredCorpusSchemaVersion === SUBJECT_PRACTICE_STRUCTURED_SOURCE_CORPUS_SCHEMA_VERSION
    && evidence.normalizationVersion === SUBJECT_PRACTICE_SOURCE_CORPUS_NORMALIZATION_VERSION
    && evidence.sourceCorpusInventoryComplete === true
    && evidence.sourceCorpusInventoryMode === 'all_active_subject_source_questions_at_statement_snapshot'
    && evidence.failClosed === true
    && evidence.sourceContentExposedToGenerator === false);
  if (!evidence || completeClearEvidence) return review;
  const issueCode = evidence.status === 'blocked'
    ? 'candidate_known_source_leakage_blocked'
    : evidence.status === 'ambiguous'
      ? 'candidate_known_source_similarity_ambiguous'
      : 'candidate_known_source_corpus_missing';
  const dimensions = review.dimensions.filter((dimension) => dimension.key !== 'duplicate_risk');
  dimensions.push({
    key: 'duplicate_risk',
    status: 'failed',
    note: `Automated candidate leakage gate failed closed: ${evidence.status}.`
  });
  return {
    ...review,
    status: 'failed',
    decision: 'regenerate',
    issues: [
      ...review.issues.filter((issue) => issue.code !== issueCode),
      { code: issueCode, severity: 'error', message: '候选题未通过当前已知真题库的自动泄漏检测。' }
    ],
    dimensions,
    sources: Array.from(new Set([...review.sources, 'deterministic']))
  };
}

export type SubjectPracticeSourceCorpusRow = {
  id: number;
  documentId: number;
  questionNumber: string;
  subject: string;
  language: string;
  promptText: string | null;
  options: unknown;
  correctAnswer: string | null;
  explanation: string | null;
};

export function subjectPracticeAutomatedCandidateLeakageEvidenceForRows(
  candidate: GeneratedQuestionCandidate,
  rows: SubjectPracticeSourceCorpusRow[]
): SubjectPracticeAutomatedCandidateLeakageGateEvidence {
  if (!rows.length) {
    return {
      policyVersion: SUBJECT_PRACTICE_CANDIDATE_OUTPUT_NOVELTY_POLICY_VERSION,
      status: 'missing_corpus',
      scannedRevisionCount: 0,
      blockedRevisionCount: 0,
      ambiguousRevisionCount: 0,
      reasonCodes: ['current_known_source_corpus_empty'],
      revisionMatchSetSha256: null,
      revisionMatchDigestVersion: SUBJECT_PRACTICE_CANDIDATE_NOVELTY_MATCH_DIGEST_VERSION,
      structuredCorpusSchemaVersion: SUBJECT_PRACTICE_STRUCTURED_SOURCE_CORPUS_SCHEMA_VERSION,
      normalizationVersion: SUBJECT_PRACTICE_SOURCE_CORPUS_NORMALIZATION_VERSION,
      sourceCorpusSnapshotSha256: null,
      sourceCorpusSnapshotVersion: SUBJECT_PRACTICE_CANDIDATE_NOVELTY_CORPUS_SNAPSHOT_VERSION,
      sourceCorpusRevisionCount: 0,
      sourceCorpusInventoryComplete: false,
      sourceCorpusInventoryMode: 'all_active_subject_source_questions_at_statement_snapshot',
      failClosed: true,
      sourceContentExposedToGenerator: false
    };
  }
  const sourceRevisions = rows.map((row) => buildSubjectPracticeStructuredSourceQuestionRevision({
    sourceSystem: 'production_database',
    documentId: String(row.documentId),
    questionOrdinal: cleanString(row.questionNumber) || String(row.id),
    subject: row.subject,
    language: row.language,
    prompt: row.promptText,
    options: row.options,
    answer: row.correctAnswer,
    explanation: row.explanation
  }));
  const novelty = evaluateSubjectPracticeCandidateOutputNovelty({ candidate, sourceRevisions });
  return {
    policyVersion: novelty.policyVersion,
    status: novelty.status,
    scannedRevisionCount: novelty.scannedRevisionCount,
    blockedRevisionCount: novelty.blockedRevisionCount,
    ambiguousRevisionCount: novelty.ambiguousRevisionCount,
    reasonCodes: novelty.reasonCodes,
    revisionMatchSetSha256: novelty.revisionMatchSetSha256,
    revisionMatchDigestVersion: novelty.revisionMatchDigestVersion,
    structuredCorpusSchemaVersion: novelty.structuredCorpusSchemaVersion,
    normalizationVersion: novelty.normalizationVersion,
    sourceCorpusSnapshotSha256: subjectPracticeCandidateNoveltyCorpusSnapshotSha256(sourceRevisions),
    sourceCorpusSnapshotVersion: SUBJECT_PRACTICE_CANDIDATE_NOVELTY_CORPUS_SNAPSHOT_VERSION,
    sourceCorpusRevisionCount: sourceRevisions.length,
    sourceCorpusInventoryComplete: sourceRevisions.length === rows.length,
    sourceCorpusInventoryMode: 'all_active_subject_source_questions_at_statement_snapshot',
    failClosed: true,
    sourceContentExposedToGenerator: false
  };
}

export type SubjectPracticeStyleSourceRow = {
  id: number;
  questionNumber: string;
  promptText: string | null;
};

export function subjectPracticeSourceSimilarityForRows(
  candidate: GeneratedQuestionCandidate,
  generationMetadata: unknown,
  rows: SubjectPracticeStyleSourceRow[]
) {
  const metadata = recordFrom(generationMetadata) ?? {};
  const styleProfile = recordFrom(metadata.styleProfile) ?? {};
  const profileId = Number(styleProfile.id);
  if (!Number.isInteger(profileId) || profileId <= 0) {
    return { checked: false, reason: 'style_profile_absent', maxSimilarity: 0, matches: [] };
  }
  const ids = Array.isArray(styleProfile.sourceQuestionIds)
    ? styleProfile.sourceQuestionIds.map((id) => Number(id)).filter((id) => Number.isInteger(id) && id > 0)
    : [];
  if (!ids.length) return { checked: false, reason: 'style_profile_source_ids_absent', maxSimilarity: 0, matches: [] };
  const idSet = new Set(ids);
  const candidateText = normalizedSimilarityText(candidate.prompt);
  const candidateTokens = similarityTokens(candidate.prompt);
  const matches = rows
    .filter((row) => idSet.has(Number(row.id)))
    .map((row) => {
      const sourceText = normalizedSimilarityText(row.promptText);
      const tokenSimilarity = jaccardSimilarity(candidateTokens, similarityTokens(sourceText));
      const containment = candidateText && sourceText
        ? (candidateText.includes(sourceText) || sourceText.includes(candidateText) ? 1 : 0)
        : 0;
      return {
        sourceQuestionId: row.id,
        questionNumber: row.questionNumber,
        similarity: Number(Math.max(tokenSimilarity, containment).toFixed(3))
      };
    })
    .sort((a, b) => b.similarity - a.similarity)
    .slice(0, 5);
  return {
    checked: true,
    profileId,
    maxSimilarity: matches[0]?.similarity ?? 0,
    matches
  };
}

