function sourceQuestionForTopicMapper(question: SourceQuestionRow) {
  const usagePolicy = defaultSourceUsagePolicy(question.sourceUsagePolicy);
  if (usagePolicy.allowPromptRawText === true) {
    return {
      id: question.id,
      subject: question.subject,
      questionNumber: question.questionNumber,
      promptText: question.promptText,
      options: question.options,
      correctAnswer: question.correctAnswer,
      explanation: question.explanation,
      analysis: question.analysis
    };
  }
  return {
    id: question.id,
    subject: question.subject,
    questionNumber: question.questionNumber,
    promptText: null,
    options: null,
    correctAnswer: null,
    explanation: null,
    analysis: {
      ...(recordFrom(question.analysis) ?? {}),
      sourceRawTextRestricted: true,
      promptHash: question.promptHash,
      blueprintLikeTags: optionalStringArray(question.blueprintLikeTags),
      topicCodes: optionalStringArray(question.topicCodes)
    }
  };
}

function mapTopicOption(row: TopicOptionRow) {
  return {
    id: row.id,
    subject: row.subject,
    code: row.code,
    title: row.title,
    module: row.module,
    syllabusVersion: row.syllabusVersion,
    status: row.status
  };
}

function sourceQuestionPinnedTopicKeys(question: Pick<SourceQuestionRow, 'topicId' | 'topicCode' | 'topicCodes' | 'analysis'>) {
  const analysis = recordFrom(question.analysis) ?? {};
  const profile = recordFrom(analysis.profile);
  const codes = new Set([
    cleanString(question.topicCode),
    ...optionalStringArray(question.topicCodes),
    cleanString(analysis.topicCode),
    ...optionalStringArray(analysis.topicCodes),
    cleanString(profile?.topicCode),
    ...optionalStringArray(profile?.topicCodes)
  ].filter(Boolean));
  const ids = new Set<number>();
  if (Number.isInteger(question.topicId) && Number(question.topicId) > 0) ids.add(Number(question.topicId));
  return { ids, codes };
}

function topicMappingCandidateIsPinned(question: Pick<SourceQuestionRow, 'topicId' | 'topicCode' | 'topicCodes' | 'analysis'>, topic: TopicMappingOptionRow) {
  const pinned = sourceQuestionPinnedTopicKeys(question);
  return pinned.ids.has(topic.id) || pinned.codes.has(topic.code);
}

function sourceQuestionMatchesPinnedTopic(question: Pick<SourceQuestionRow, 'topicId' | 'topicCode' | 'topicCodes' | 'analysis'>, topic: { topicId?: number | null; topicCode?: string | null }) {
  const pinned = sourceQuestionPinnedTopicKeys(question);
  return (Number.isInteger(topic.topicId) && pinned.ids.has(Number(topic.topicId)))
    || Boolean(cleanString(topic.topicCode) && pinned.codes.has(cleanString(topic.topicCode)));
}

function topicMapperTopicFromOption(topic: TopicMappingOptionRow): TopicMapperTopic {
  return {
    id: topic.id,
    code: topic.code,
    title: topic.title,
    module: topic.module,
    description: topic.description,
    examScope: topic.examScope,
    skills: optionalStringArray(topic.skills),
    aliases: optionalStringArray(topic.aliases),
    excludedScope: optionalStringArray(topic.excludedScope)
  };
}

function topicMappingText(question: Pick<SourceQuestionRow, 'promptText' | 'options' | 'correctAnswer' | 'explanation' | 'topicCode' | 'topicCodes' | 'analysis' | 'blueprintLikeTags'>) {
  const options = Array.isArray(question.options)
    ? question.options.map((item) => cleanString(recordFrom(item)?.text ?? item)).join(' ')
    : '';
  const analysis = recordFrom(question.analysis) ?? {};
  const profile = recordFrom(analysis.profile);
  return [
    question.promptText,
    options,
    question.correctAnswer,
    question.explanation,
    question.topicCode,
    optionalStringArray(question.topicCodes).join(' '),
    optionalStringArray(question.blueprintLikeTags).join(' '),
    cleanString(analysis.topicCode),
    optionalStringArray(analysis.topicCodes).join(' '),
    cleanString(profile?.topicCode),
    optionalStringArray(profile?.topicCodes).join(' '),
    cleanString(analysis.cognitiveSkill),
    cleanString(analysis.questionForm),
    optionalStringArray(analysis.keyConcepts).join(' '),
    optionalStringArray(analysis.styleNotes).join(' ')
  ].map((item) => cleanString(item).toLowerCase()).filter(Boolean).join(' ');
}

function topicMappingCandidateText(topic: TopicMappingOptionRow) {
  return [
    topic.code,
    topic.title,
    topic.module,
    topic.description,
    topic.examScope,
    optionalStringArray(topic.skills).join(' '),
    optionalStringArray(topic.aliases).join(' ')
  ].map((item) => cleanString(item).toLowerCase()).filter(Boolean).join(' ');
}

function tokenizeForTopicMapping(value: string) {
  return Array.from(new Set(value
    .replace(/[^\p{L}\p{N}\-]+/gu, ' ')
    .split(/\s+/)
    .map((item) => item.trim().toLowerCase())
    .filter((item) => item.length >= 2)));
}

function topicMappingLexicalScore(questionText: string, topic: TopicMappingOptionRow) {
  const topicText = topicMappingCandidateText(topic);
  const questionTokens = new Set(tokenizeForTopicMapping(questionText));
  const topicTokens = tokenizeForTopicMapping(topicText);
  let score = 0;
  for (const token of topicTokens) {
    if (questionTokens.has(token)) score += token.length >= 5 ? 3 : 1;
  }
  if (topic.title && questionText.includes(topic.title.toLowerCase())) score += 12;
  if (topic.module && questionText.includes(topic.module.toLowerCase())) score += 4;
  for (const skill of optionalStringArray(topic.skills)) {
    const text = skill.toLowerCase();
    if (text && questionText.includes(text)) score += 8;
  }
  for (const alias of optionalStringArray(topic.aliases)) {
    const text = alias.toLowerCase();
    if (text && questionText.includes(text)) score += 6;
  }
  return score;
}

function shortlistTopicMappingCandidates(question: SourceQuestionRow, topics: TopicMappingOptionRow[], limit = 12): TopicMapperTopic[] {
  const questionText = topicMappingText(question);
  const ranked = topics
    .map((topic) => ({ topic, score: topicMappingLexicalScore(questionText, topic) }))
    .sort((left, right) => right.score - left.score || left.topic.code.localeCompare(right.topic.code));
  const pinnedCandidates = ranked.filter(({ topic }) => topicMappingCandidateIsPinned(question, topic));
  const selectedCandidateLimit = Math.max(3, Math.min(limit, topics.length), pinnedCandidates.length);
  const selected = new Map<number, TopicMappingOptionRow>();
  for (const { topic } of pinnedCandidates) selected.set(topic.id, topic);
  for (const { topic } of ranked) {
    if (selected.size >= selectedCandidateLimit) break;
    selected.set(topic.id, topic);
  }
  return Array.from(selected.values()).map(topicMapperTopicFromOption);
}

function fallbackTopicMappingSuggestion(question: SourceQuestionRow, topics: TopicMappingOptionRow[]): TopicMapperSuggestion[] {
  const questionText = topicMappingText(question);
  const ranked = topics
    .map((topic) => ({ topic, score: topicMappingLexicalScore(questionText, topic) }))
    .filter((item) => item.score > 0)
    .sort((left, right) => right.score - left.score || left.topic.code.localeCompare(right.topic.code))
    .slice(0, 3);
  if (!ranked.length) return [];
  const topScore = Math.max(ranked[0].score, 1);
  return ranked.map(({ topic, score }) => ({
    topicCode: topic.code,
    confidence: Math.min(0.74, Math.max(0.35, score / (topScore + 8))),
    reason: `规则预筛：题目文本与「${topic.title}」的大纲标题、范围或技能词有重合。`
  }));
}

function cachedSuccessfulTopicMappingSuggestions(question: SourceQuestionRow, topics: TopicMappingOptionRow[]): TopicMapperSuggestion[] {
  const analysis = recordFrom(question.analysis);
  const mapping = recordFrom(analysis?.aiTopicMapping);
  const status = cleanString(mapping?.status).toLowerCase();
  if (!status.includes('success')) return [];
  const validCodes = new Set(topics.map((topic) => topic.code));
  const suggestionsInput = Array.isArray(mapping?.suggestions) ? mapping.suggestions : [];
  const suggestions = suggestionsInput
    .map((item) => {
      const record = recordFrom(item);
      const topicCode = cleanString(record?.topicCode);
      const confidence = Number(record?.confidence ?? 0);
      const reason = cleanString(record?.reason, '复用已成功的真题知识点映射。');
      if (!topicCode || !validCodes.has(topicCode) || !Number.isFinite(confidence) || confidence <= 0) return null;
      return {
        topicCode,
        confidence: Math.max(0, Math.min(1, confidence)),
        reason
      };
    })
    .filter(Boolean)
    .sort((left, right) => right!.confidence - left!.confidence)
    .slice(0, 3) as TopicMapperSuggestion[];
  const top = suggestions[0];
  if (!top) return [];
  const second = suggestions[1];
  const topTopic = topics.find((topic) => topic.code === top.topicCode);
  const thresholds = autoProfileGateThresholds(question.subject);
  const trustedSourceTopicMatch = topTopic
    ? sourceQuestionMatchesPinnedTopic(question, { topicId: topTopic.id, topicCode: topTopic.code })
    : false;
  const effectiveMinConfidence = trustedSourceTopicMatch
    ? Math.min(thresholds.minConfidence, AUTO_PROFILE_TRUSTED_SOURCE_TOPIC_MIN_CONFIDENCE)
    : thresholds.minConfidence;
  const confidenceGap = Number(top.confidence ?? 0) - Number(second?.confidence ?? 0);
  if (Number(top.confidence ?? 0) < effectiveMinConfidence || confidenceGap < thresholds.minConfidenceGap) return [];
  return suggestions;
}

function topicMappingAnalysisPatch(input: {
  question: SourceQuestionRow;
  suggestions: Array<TopicMapperSuggestion & { topicId?: number; topicTitle?: string | null; module?: string | null }>;
  provider: string;
  model: string;
  status: string;
  error?: string;
  agent: unknown;
  candidateTopicCodes: string[];
}) {
  const analysis = recordFrom(input.question.analysis) ?? {};
  return {
    ...analysis,
    aiTopicMapping: {
      agent: input.agent,
      provider: input.provider,
      model: input.model,
      status: input.status,
      error: input.error ?? null,
      generatedAt: new Date().toISOString(),
      candidateTopicCodes: input.candidateTopicCodes,
      suggestions: input.suggestions,
      topConfidence: input.suggestions[0]?.confidence ?? 0
    }
  };
}

function autoProfileRetryableFailure(status: string) {
  return [
    'gateway_concurrency_timeout',
    'gateway_no_key_available',
    'gateway_key_concurrency_saturated',
    'gateway_key_rate_limited',
    'gateway_key_cooldown',
    'gateway_timeout',
    'no_key_available',
    'provider_timeout',
    'provider_empty_output',
    'provider_rate_limited',
    'provider_network_error',
    'provider_schema_invalid',
    'provider_unavailable',
    'provider_error',
    'gateway_unknown_error'
  ].some((prefix) => status === prefix || status.startsWith(prefix) || status.includes('timeout') || status.includes('unavailable'));
}

function autoProfileShouldYieldAfterReason(reasonCode: string) {
  return [
    'gateway_no_key_available',
    'gateway_key_concurrency_saturated',
    'gateway_key_rate_limited',
    'gateway_key_cooldown',
    'no_key_available',
    'gateway_concurrency_timeout',
    'provider_timeout',
    'provider_empty_output',
    'provider_rate_limited',
    'provider_network_error',
    'provider_quota_exceeded',
    'provider_unavailable',
    'gateway_unknown_error'
  ].some((prefix) => reasonCode === prefix || reasonCode.startsWith(prefix));
}

function generationJobShouldYieldAfterProviderBackpressure(job: { error?: unknown; promptMetadata?: unknown; governance?: { failureCategory?: string | null } }) {
  const metadata = recordFrom(job.promptMetadata) ?? {};
  const failureCategory = cleanString(job.governance?.failureCategory ?? metadata.failureCategory).toLowerCase();
  const error = cleanString(job.error).toLowerCase();
  return [
    'gateway_no_key_available',
    'gateway_key_concurrency_saturated',
    'gateway_key_rate_limited',
    'gateway_key_cooldown',
    'no_key_available',
    'gateway_concurrency_timeout',
    'provider_timeout',
    'provider_network_error',
    'provider_rate_limited',
    'provider_quota_exceeded',
    'provider_unavailable',
    'gateway_unknown_error'
  ].some((prefix) => failureCategory === prefix || failureCategory.startsWith(prefix) || error.includes(prefix))
    || error.includes('no ai provider key is available');
}

function normalizeAutoProfileBatchLimit(value: unknown, action: SourceQuestionAutoProfileTaskAction) {
  return cleanPositiveInt(
    value,
    action === 'retry_failed_samples' ? AUTO_PROFILE_RETRY_CHUNK_LIMIT : AUTO_PROFILE_DEFAULT_CHUNK_LIMIT,
    1,
    AUTO_PROFILE_MAX_CHUNK_LIMIT
  );
}

function autoProfileGateDefaults(subject: unknown) {
  return SUBJECT_AUTO_PROFILE_GATE_DEFAULTS[cleanString(subject).toLowerCase()] ?? {
    minConfidence: AUTO_PROFILE_MIN_CONFIDENCE,
    minConfidenceGap: AUTO_PROFILE_MIN_CONFIDENCE_GAP
  };
}

function normalizeAutoProfileGateThreshold(value: unknown, fallback: number) {
  const next = Number(value);
  return Number.isFinite(next) ? Math.max(0, Math.min(1, next)) : fallback;
}

function autoProfileGateThresholds(subject: unknown, input: Record<string, unknown> = {}) {
  const defaults = autoProfileGateDefaults(subject);
  return {
    minConfidence: normalizeAutoProfileGateThreshold(input.minConfidence, defaults.minConfidence),
    minConfidenceGap: normalizeAutoProfileGateThreshold(input.minConfidenceGap, defaults.minConfidenceGap)
  };
}

function sourceProfileRequiredMappingCoverage(subject: unknown) {
  return SUBJECT_SOURCE_PROFILE_REQUIRED_MAPPING_COVERAGE[cleanString(subject).toLowerCase()]
    ?? SOURCE_PROFILE_REQUIRED_MAPPING_COVERAGE;
}

function withAutoProfileTimeout<T>(promise: Promise<T>, timeoutMs = AUTO_PROFILE_SINGLE_QUESTION_TIMEOUT_MS): Promise<T> {
  return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error('provider_timeout: source question auto profile timed out')), timeoutMs);
    promise
      .then(resolve, reject)
      .finally(() => clearTimeout(timeout));
  });
}

function sourceQuestionHasFatalAnalysisIssue(question: SourceQuestionRow) {
  const issues = Array.isArray(question.analysisIssues) ? question.analysisIssues : [];
  return issues.some((item) => {
    const record = recordFrom(item);
    const severity = cleanString(record?.severity).toLowerCase();
    const code = cleanString(record?.code).toLowerCase();
    return severity === 'error' || code.includes('fatal') || code.includes('missing_prompt') || code.includes('out_of_scope');
  });
}

function autoProfileReasonMessage(reasonCode: string) {
  const labels: Record<string, string> = {
    passed: '自动画像门禁通过。',
    usage_policy_blocked: '来源 usage policy 不允许用于画像。',
    missing_required_structure: '题目缺少自动画像所需的题干或结构化解析。',
    source_diagram_unavailable: '题目完全依赖缺失图片或图表，当前不纳入画像。',
    out_of_syllabus: 'AI 判断结果无法贴合当前大纲范围。',
    topic_not_found: 'AI 建议的知识点不在当前学科大纲中。',
    low_confidence: 'AI 映射置信度低于自动纳入阈值。',
    ambiguous_topic: 'AI 前两名知识点置信度过近。',
    conflicting_analysis: '题目解析存在冲突或致命问题。',
    unsupported_question_type: '题型暂不适合进入画像。',
    provider_timeout: 'AI 映射超时，可自动重试。',
    provider_rate_limited: 'AI provider 限流，可延迟重试。',
    provider_network_error: 'AI provider 网络失败，可自动重试。',
    provider_schema_invalid: 'AI 输出结构无效，可自动重试。',
    provider_error: 'AI provider 临时失败，可自动重试。',
    gateway_unknown_error: 'AI 网关/provider 临时失败，可自动重试。',
    gateway_no_key_available: 'AI 网关暂无可用 Key，可自动重试。',
    no_key_available: 'AI 网关暂无可用 Key，可自动重试。',
    retry_exhausted: '自动重试次数已耗尽。'
  };
  return labels[reasonCode] ?? reasonCode;
}

function sourceQuestionTextQualityIssues(input: { prompt: string; options?: unknown; explanation?: unknown }) {
  const issues: string[] = [];
  const fields = [
    { label: '题干', value: input.prompt },
    { label: '解析', value: cleanString(input.explanation) }
  ];
  if (Array.isArray(input.options)) {
    input.options.forEach((option, index) => {
      const record = recordFrom(option);
      fields.push({ label: `选项 ${cleanString(record?.id, String(index + 1))}`, value: cleanString(record?.text) });
    });
  }
  const artifactGlyphPattern = /[ǅǆǊǒǜǝƫƬƭƮƺư]/;
  const watermarkPattern = /\b(CSCA\s+Academy|Sold\s+to|misakitoufu@gmail\.com)\b/i;
  const duplicateExpressionPattern = /([A-Za-z]\s*[=∈:]?\s*[\{\(\[][^。；;,.，]{3,80}[\}\)\]])\s*\1/;
  const lostSuperscriptPattern = /\b[xyz][234]\b/;
  for (const field of fields) {
    if (!field.value) continue;
    if (artifactGlyphPattern.test(field.value)) issues.push(`${field.label}包含 PDF 字体编码乱码。`);
    if (watermarkPattern.test(field.value)) issues.push(`${field.label}包含水印或购买账号残留。`);
    if (duplicateExpressionPattern.test(field.value)) issues.push(`${field.label}疑似存在公式/集合表达式重复抽取。`);
    if (lostSuperscriptPattern.test(field.value)) issues.push(`${field.label}疑似存在上标丢失，例如 x2/y2 应写为 x^2/y^2 或对应 LaTeX。`);
  }
  return Array.from(new Set(issues));
}

export type SourceQuestionImageDependencyStatus = {
  status: 'text_only' | 'textualized_visual' | 'missing_visual_dependency';
  reasonCode: string | null;
  evidence: string[];
};

function sourceQuestionHasStructuredVisualContext(question: Record<string, unknown>, analysis: Record<string, unknown>) {
  const visualFields = [
    'imageDescription',
    'figureDescription',
    'diagramDescription',
    'visualDescription',
    'graphDescription',
    'imageText',
    'figureText',
    'diagramText'
  ];
  if (visualFields.some((field) => cleanString(question[field]))) return true;
  const sourceMeta = recordFrom(question.sourceMeta) ?? {};
  if (visualFields.some((field) => cleanString(sourceMeta[field]))) return true;
  const styleNotes = optionalStringArray(analysis.styleNotes ?? (recordFrom(analysis.profile) ?? {}).styleNotes);
  if (styleNotes.some((note) => /diagram_textualized|visual_textualized|figure_textualized/.test(note))) return true;
  const prompt = cleanString(question.prompt ?? question.promptText).toLowerCase();
  return /\b(diagram|figure|graph)\s*:/.test(prompt);
}

function sourceQuestionIssueCodes(value: unknown) {
  if (!Array.isArray(value)) return [];
  return value
    .map((item) => {
      const record = recordFrom(item);
      return cleanString(record?.code ?? record?.message ?? item);
    })
    .filter(Boolean);
}

export function sourceQuestionImageDependencyStatus(input: {
  question: Record<string, unknown>;
  analysis?: unknown;
}): SourceQuestionImageDependencyStatus {
  const question = input.question;
  const analysis = recordFrom(input.analysis ?? question.analysis) ?? {};
  const profile = recordFrom(analysis.profile) ?? {};
  const prompt = cleanString(question.prompt ?? question.promptText);
  const explanation = cleanString(question.explanation);
  const text = `${prompt} ${explanation}`.toLowerCase();
  const styleNotes = optionalStringArray(analysis.styleNotes ?? profile.styleNotes);
  const profileIssues = [
    ...sourceQuestionIssueCodes(analysis.profileIssues),
    ...sourceQuestionIssueCodes(profile.profileIssues),
    ...sourceQuestionIssueCodes(question.analysisIssues)
  ].map((issue) => issue.toLowerCase());
  const explicitUnavailable = [...styleNotes, ...profileIssues].some((issue) => (
    /source_diagram_unavailable|missing_diagram|missing_figure|missing_graph|image_required_not_supported/.test(issue)
  ));
  const hasVisualCue = Boolean(
    (recordFrom(analysis.stemPattern) ?? {}).hasDiagram === true
    || (recordFrom(profile.stemPattern) ?? {}).hasDiagram === true
    || styleNotes.some((note) => /figure|diagram|graph|visual/.test(note.toLowerCase()))
    || /\b(as shown|shown in the figure|shown below|diagram|figure|graph|field lines|x-t|v-t|f-t|p-v|curve|plot)\b/i.test(text)
  );
  if (!hasVisualCue) return { status: 'text_only', reasonCode: null, evidence: [] };
  if (sourceQuestionHasStructuredVisualContext(question, analysis)) {
    return { status: 'textualized_visual', reasonCode: null, evidence: ['visual_context_textualized'] };
  }
  const hardMissingVisualCue = [
    /\b(the graph|graph showing|curve shown|plot shown|x-t graph|v-t graph|f-t graph|p-v graph)\b/i,
    /\b(electric field lines|field lines).*\bshown\b/i,
    /\btrajectory\b.*\bcurve shown\b/i
  ].some((pattern) => pattern.test(text));
  const dependsOnMissingVisual = explicitUnavailable || hardMissingVisualCue;
  if (!dependsOnMissingVisual) return { status: 'textualized_visual', reasonCode: null, evidence: ['visual_cue_without_hard_dependency'] };
  return {
    status: 'missing_visual_dependency',
    reasonCode: 'source_diagram_unavailable',
    evidence: explicitUnavailable
      ? ['source_json_marks_visual_unavailable']
      : ['source_question_references_missing_visual_context']
  };
}

function buildAutoProfileGateResult(input: {
  reasonCode: string;
  status: SourceQuestionAutoProfileStatus;
  confidence?: number;
  confidenceGap?: number;
  topicCode?: string | null;
  evidence?: string[];
  retryable?: boolean;
}) {
  return {
    passed: input.status === 'auto_approved',
    status: input.status,
    reasonCode: input.reasonCode,
    confidence: input.confidence ?? null,
    confidenceGap: input.confidenceGap ?? null,
    topicCode: input.topicCode ?? null,
    evidence: input.evidence ?? [autoProfileReasonMessage(input.reasonCode)],
    retryable: input.retryable === true
  };
}

