function numberListFromUnknown(value: unknown, fallback: number[] = []) {
  if (!Array.isArray(value)) return fallback;
  return Array.from(new Set(value.map((item) => Number(item)).filter((item) => Number.isInteger(item) && item > 0)));
}

function generationProfileMetadata(profile?: ReturnType<typeof mapGenerationProfile> | null): Record<string, unknown> {
  if (!profile) return { generationProfile: null };
  const profileRecord = recordFrom(profile.profile) ?? {};
  const targetPolicy = recordFrom(profile.targetPolicy) ?? {};
  const seriesProfileRecord = recordFrom(profileRecord.seriesProfile) ?? {};
  const sourceSnapshotHash = cleanString(
    profileRecord.sourceSnapshotHash
      ?? targetPolicy.sourceSnapshotHash
      ?? seriesProfileRecord.sourceSnapshotHash
  ) || null;
  const syllabusSnapshotHash = cleanString(
    profileRecord.syllabusSnapshotHash
      ?? targetPolicy.syllabusSnapshotHash
      ?? seriesProfileRecord.syllabusSnapshotHash
  ) || null;
  const profileWindow = cleanString(
    profileRecord.profileWindow
      ?? profileRecord.sourceWindow
      ?? profileRecord.window
      ?? targetPolicy.profileWindow
      ?? targetPolicy.sourceWindow
      ?? targetPolicy.window
  ) || null;
  const profilePolicyVersion = cleanString(
    profileRecord.profilePolicyVersion
      ?? profileRecord.policyVersion
      ?? targetPolicy.profilePolicyVersion
      ?? targetPolicy.policyVersion
  ) || null;
  const sourceProfileIds = numberListFromUnknown(
    profileRecord.sourceProfileIds ?? targetPolicy.sourceProfileIds,
    profile.sourceStyleProfileId ? [profile.sourceStyleProfileId] : []
  );
  const reference = {
    id: profile.id,
    useCase: profile.useCase,
    confidence: profile.confidence,
    sampleSize: profile.sampleSize,
    seriesProfileId: profile.seriesProfileId,
    sourceStyleProfileId: profile.sourceStyleProfileId,
    sourceProfileIds,
    sourceSnapshotHash,
    syllabusSnapshotHash,
    profileWindow,
    profilePolicyVersion,
    referencePolicy: 'profile_only'
  };
  return {
    generationProfileId: profile.id,
    seriesProfileId: profile.seriesProfileId,
    sourceStyleProfileId: profile.sourceStyleProfileId,
    sourceProfileIds,
    sourceSnapshotHash,
    syllabusSnapshotHash,
    profileWindow,
    profilePolicyVersion,
    generationProfile: reference
  };
}

function generationProfileLineageFromMetadata(value: unknown) {
  const metadata = recordFrom(value) ?? {};
  const nested = recordFrom(metadata.generationProfile) ?? {};
  const generationProfileId = Number(metadata.generationProfileId ?? nested.id);
  const sourceSnapshotHash = cleanString(metadata.sourceSnapshotHash ?? nested.sourceSnapshotHash) || null;
  const syllabusSnapshotHash = cleanString(metadata.syllabusSnapshotHash ?? nested.syllabusSnapshotHash) || null;
  return {
    hasLineage: (Number.isInteger(generationProfileId) && generationProfileId > 0)
      || Boolean(sourceSnapshotHash)
      || Boolean(syllabusSnapshotHash),
    generationProfileId: Number.isInteger(generationProfileId) && generationProfileId > 0 ? generationProfileId : null,
    sourceSnapshotHash,
    syllabusSnapshotHash
  };
}

function generationProfileLineageIsStale(queued: ReturnType<typeof generationProfileLineageFromMetadata>, current: Record<string, unknown>) {
  const currentGenerationProfileId = Number(current.generationProfileId);
  const currentSourceSnapshotHash = cleanString(current.sourceSnapshotHash) || null;
  const currentSyllabusSnapshotHash = cleanString(current.syllabusSnapshotHash) || null;
  const currentHasLineage = (Number.isInteger(currentGenerationProfileId) && currentGenerationProfileId > 0)
    || Boolean(currentSourceSnapshotHash)
    || Boolean(currentSyllabusSnapshotHash);
  if (!queued.hasLineage) return currentHasLineage;
  if (queued.generationProfileId && Number.isInteger(currentGenerationProfileId) && currentGenerationProfileId > 0 && queued.generationProfileId !== currentGenerationProfileId) return true;
  if (queued.sourceSnapshotHash && currentSourceSnapshotHash && queued.sourceSnapshotHash !== currentSourceSnapshotHash) return true;
  if (queued.syllabusSnapshotHash && currentSyllabusSnapshotHash && queued.syllabusSnapshotHash !== currentSyllabusSnapshotHash) return true;
  return false;
}

function generationProfileStableSnapshotLineage(metadata: Record<string, unknown> | null | undefined) {
  if (!metadata) return null;
  const sourceSnapshotHash = cleanString(metadata.sourceSnapshotHash) || null;
  const syllabusSnapshotHash = cleanString(metadata.syllabusSnapshotHash) || null;
  return sourceSnapshotHash || syllabusSnapshotHash
    ? { sourceSnapshotHash, syllabusSnapshotHash }
    : metadata;
}

function studentConsumableAiVersionSql() {
  return Prisma.sql`('current', 'legacy_usable', 'manual_published')`;
}

function generationProfileLineageFreshFilterSql(
  metadataExpression: Prisma.Sql,
  current: Record<string, unknown> | null | undefined
) {
  const generationProfileId = Number(current?.generationProfileId);
  const sourceSnapshotHash = cleanString(current?.sourceSnapshotHash) || null;
  const syllabusSnapshotHash = cleanString(current?.syllabusSnapshotHash) || null;
  const clauses: Prisma.Sql[] = [];
  if (Number.isInteger(generationProfileId) && generationProfileId > 0) {
    clauses.push(Prisma.sql`(
      ${metadataExpression}->>'generationProfileId' ~ '^[0-9]+$'
      AND (${metadataExpression}->>'generationProfileId')::int = ${generationProfileId}
    )`);
  }
  if (sourceSnapshotHash) {
    clauses.push(Prisma.sql`COALESCE(${metadataExpression}->>'sourceSnapshotHash', '') = ${sourceSnapshotHash}`);
  }
  if (syllabusSnapshotHash) {
    clauses.push(Prisma.sql`COALESCE(${metadataExpression}->>'syllabusSnapshotHash', '') = ${syllabusSnapshotHash}`);
  }
  return clauses.length ? Prisma.sql`AND ${Prisma.join(clauses, ' AND ')}` : Prisma.empty;
}

function generationProfileLineageMismatchFilterSql(
  metadataExpression: Prisma.Sql,
  current: Record<string, unknown> | null | undefined
) {
  const generationProfileId = Number(current?.generationProfileId);
  const sourceSnapshotHash = cleanString(current?.sourceSnapshotHash) || null;
  const syllabusSnapshotHash = cleanString(current?.syllabusSnapshotHash) || null;
  const clauses: Prisma.Sql[] = [];
  if (Number.isInteger(generationProfileId) && generationProfileId > 0) {
    clauses.push(Prisma.sql`NOT (
      ${metadataExpression}->>'generationProfileId' ~ '^[0-9]+$'
      AND (${metadataExpression}->>'generationProfileId')::int = ${generationProfileId}
    )`);
  }
  if (sourceSnapshotHash) {
    clauses.push(Prisma.sql`COALESCE(${metadataExpression}->>'sourceSnapshotHash', '') <> ${sourceSnapshotHash}`);
  }
  if (syllabusSnapshotHash) {
    clauses.push(Prisma.sql`COALESCE(${metadataExpression}->>'syllabusSnapshotHash', '') <> ${syllabusSnapshotHash}`);
  }
  return clauses.length ? Prisma.sql`OR ${Prisma.join(clauses, ' OR ')}` : Prisma.empty;
}

function versionGovernanceFromMetadata(value: unknown) {
  return recordFrom(recordFrom(value)?.versionGovernance) ?? {};
}

function approvedConsumableVersionGovernance(
  current: Record<string, unknown>,
  input: {
    targetUseCase: 'subject_practice' | 'online_mock_exam';
    approvalStatus: string;
    approvalSource: string;
    decidedAt: string;
    fallbackReason: string;
  }
) {
  const currentStatus = cleanString(current.status);
  const status = isStudentConsumableAiVersionStatus(currentStatus)
    ? currentStatus
    : 'legacy_usable';
  return {
    ...current,
    status,
    reason: isStudentConsumableAiVersionStatus(currentStatus)
      ? cleanString(current.reason, input.fallbackReason)
      : input.fallbackReason,
    targetUseCase: input.targetUseCase,
    approval: {
      status: input.approvalStatus,
      decidedAt: input.decidedAt,
      source: input.approvalSource
    }
  };
}

function questionTargetUseCaseFromMetadata(value: unknown): 'subject_practice' | 'online_mock_exam' {
  const metadata = recordFrom(value) ?? {};
  const scope = recordFrom(metadata.scope) ?? {};
  const targetUseCase = cleanString(metadata.targetUseCase ?? scope.targetUseCase);
  if (targetUseCase === 'online_mock_exam' || isMockExamOnlyGeneration(value)) return 'online_mock_exam';
  return 'subject_practice';
}

function questionGenerationLooksSyntheticTest(value: unknown) {
  const metadata = recordFrom(value) ?? {};
  return questionGenerationUsedFallback(value)
    || cleanString(metadata.generator) === 'rule-fallback'
    || cleanString(metadata.sourceKind).toLowerCase().includes('smoke')
    || cleanString(metadata.generationSource).toLowerCase().includes('smoke')
    || cleanString(metadata.generationMode).toLowerCase().includes('smoke');
}

function classifyQuestionVersionGovernance(input: {
  question: QuestionVersionGovernanceRow;
  activeProfile: ReturnType<typeof mapGenerationProfile> | null;
  activeMetadata: Record<string, unknown> | null;
}) {
  const generatedAt = new Date().toISOString();
  const question = input.question;
  const generation = recordFrom(question.generationMetadata) ?? {};
  const existingVersionGovernance = versionGovernanceFromMetadata(generation);
  const existingVersionStatus = cleanString(existingVersionGovernance.status);
  const targetUseCase = questionTargetUseCaseFromMetadata(generation);
  const lineage = generationProfileLineageFromMetadata(generation);
  const activeGenerationProfileId = input.activeProfile?.id ?? null;
  const activeSeriesProfileId = input.activeProfile?.seriesProfileId ?? null;
  const activeSourceSnapshotHash = cleanString(input.activeMetadata?.sourceSnapshotHash) || null;
  const activeSyllabusSnapshotHash = cleanString(input.activeMetadata?.syllabusSnapshotHash) || null;
  const sourceSnapshotMatch = Boolean(lineage.sourceSnapshotHash && activeSourceSnapshotHash && lineage.sourceSnapshotHash === activeSourceSnapshotHash);
  const syllabusSnapshotMatch = Boolean(lineage.syllabusSnapshotHash && activeSyllabusSnapshotHash && lineage.syllabusSnapshotHash === activeSyllabusSnapshotHash);
  const generationProfileMatch = Boolean(lineage.generationProfileId && activeGenerationProfileId && lineage.generationProfileId === activeGenerationProfileId);
  const stableSnapshotLineageMatch = Boolean(
    lineage.sourceSnapshotHash
    && activeSourceSnapshotHash
    && sourceSnapshotMatch
    && lineage.syllabusSnapshotHash
    && activeSyllabusSnapshotHash
    && syllabusSnapshotMatch
  );
  const topicPublished = question.topicStatus === 'published' && question.topicSyllabusVersion === question.syllabusVersion;

  let status: string;
  let reason: string;
  if (['archived', 'rejected'].includes(question.status)) {
    status = 'retired';
    reason = `question_${question.status}`;
  } else if (!topicPublished) {
    status = 'stale_needs_review';
    reason = question.topicStatus === 'published' ? 'syllabus_version_mismatch' : 'topic_not_published';
  } else if (questionGenerationLooksSyntheticTest(generation)) {
    status = 'retired';
    reason = 'test_or_fallback_generation';
  } else if (existingVersionStatus === 'manual_published' && question.status === 'approved' && isStudentConsumableAiVersionStatus(existingVersionStatus)) {
    status = 'manual_published';
    reason = cleanString(existingVersionGovernance.reason, 'manual_published_preserved');
  } else if (!lineage.hasLineage) {
    status = 'unknown_legacy';
    reason = 'missing_generation_lineage';
  } else if (!input.activeProfile || !input.activeMetadata) {
    status = 'stale_needs_review';
    reason = 'active_generation_profile_missing';
  } else if (input.activeProfile.useCase !== targetUseCase) {
    status = 'stale_needs_review';
    reason = 'target_use_case_mismatch';
  } else if (generationProfileMatch && (!lineage.sourceSnapshotHash || !activeSourceSnapshotHash || sourceSnapshotMatch) && (!lineage.syllabusSnapshotHash || !activeSyllabusSnapshotHash || syllabusSnapshotMatch)) {
    status = 'current';
    reason = 'active_generation_profile_match';
  } else if (stableSnapshotLineageMatch) {
    status = 'current';
    reason = 'active_generation_snapshot_match';
  } else if (question.status === 'approved') {
    status = 'legacy_usable';
    reason = 'generation_profile_superseded_but_topic_still_active';
  } else {
    status = 'stale_needs_review';
    reason = 'candidate_not_current_or_approved';
  }

  return {
    status,
    reason,
    classifiedAt: generatedAt,
    classifiedBy: status === 'manual_published' ? cleanString(existingVersionGovernance.classifiedBy, 'manual') : 'system',
    targetUseCase,
    activeGenerationProfileId,
    questionGenerationProfileId: lineage.generationProfileId,
    activeSeriesProfileId,
    questionSeriesProfileId: Number(generation.seriesProfileId ?? recordFrom(generation.generationProfile)?.seriesProfileId) || null,
    activeSourceSnapshotHash,
    questionSourceSnapshotHash: lineage.sourceSnapshotHash,
    activeSyllabusSnapshotHash,
    questionSyllabusSnapshotHash: lineage.syllabusSnapshotHash,
    sourceSnapshotMatch,
    syllabusSnapshotMatch,
    topicStatus: question.topicStatus,
    topicSyllabusVersion: question.topicSyllabusVersion
  };
}

function generationSourceLabel(value: unknown) {
  const record = recordFrom(value);
  const sourceKind = cleanString(record?.sourceKind ?? record?.generationSource, 'syllabus');
  if (sourceKind === 'mock_exam_blueprint_slot') return '在线模考候选生成';
  if (sourceKind === 'syllabus_and_past_paper_profile') return '大纲+真题画像生成';
  if (sourceKind === 'syllabus_and_past_paper') return '大纲+真题生成';
  if (sourceKind === 'past_paper') return '真题参考生成';
  if (questionGenerationUsedFallback(value)) return 'fallback 测试生成';
  return '大纲生成';
}

function isMockExamOnlyGeneration(value: unknown) {
  const record = recordFrom(value);
  if (!record) return false;
  const scope = recordFrom(record.scope) ?? {};
  const generationMode = cleanString(record.generationMode);
  return cleanString(record.sourceKind ?? record.generationSource) === 'mock_exam_blueprint_slot'
    || generationMode === 'online_mock_exam_candidate'
    || generationMode.startsWith('online_mock_candidate_')
    || cleanString(scope.targetUseCase) === 'online_mock_exam'
    || cleanString(scope.intendedUse) === 'mock_candidate'
    || Boolean(recordFrom(record.mockExamSlot));
}

function generationIntendedUse(value: unknown) {
  const record = recordFrom(value) ?? {};
  const scope = recordFrom(record.scope) ?? {};
  const explicit = cleanString(record.intendedUse);
  if (explicit) return explicit;
  const scoped = cleanString(scope.intendedUse);
  if (scoped) return scoped;
  const targetUseCase = cleanString(scope.targetUseCase);
  if (targetUseCase === 'subject_practice') return 'subject_practice';
  if (targetUseCase === 'online_mock_exam') return 'mock_candidate';
  return '';
}

function generationSourceForBlueprint(blueprint: Pick<BlueprintRow, 'source' | 'constraints'>, hasStyleProfile: boolean) {
  const constraints = constraintsRecord(blueprint.constraints);
  const isMockExam = blueprint.source === 'mock_exam_blueprint_slot'
    || cleanString(constraints.generationSource) === 'mock_exam_blueprint_slot'
    || Boolean(recordFrom(constraints.mockExamSlot));
  if (isMockExam) {
    return {
      sourceKind: 'mock_exam_blueprint_slot',
      generationSource: 'mock_exam_blueprint_slot',
      generationMode: 'online_mock_exam_candidate',
      mockExamSlot: recordFrom(constraints.mockExamSlot)
    };
  }
  return {
    sourceKind: hasStyleProfile ? 'syllabus_and_past_paper_profile' : 'syllabus',
    generationSource: hasStyleProfile ? 'syllabus_and_past_paper_profile' : 'syllabus',
    generationMode: null,
    mockExamSlot: null
  };
}

function nullableNumber(value: unknown) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : null;
}

function aiQuestionScopeForBlueprint(
  blueprint: Pick<BlueprintRow, 'subject' | 'topicId' | 'topicCode' | 'syllabusVersion' | 'source' | 'constraints'>,
  generationSource = generationSourceForBlueprint(blueprint, Boolean(constraintsRecord(blueprint.constraints).styleProfile)),
  modeOverride?: string
) {
  const intendedUse = subjectIntendedUseForBlueprint(blueprint);
  const mockExamSlot = recordFrom(generationSource.mockExamSlot) ?? {};
  const isMockExam = intendedUse === 'mock_candidate' || generationSource.sourceKind === 'mock_exam_blueprint_slot';
  const baseMode = cleanString(modeOverride)
    || cleanString(generationSource.generationMode)
    || (isMockExam ? 'online_mock_slot_fulfillment' : 'subject_gap_fulfillment');
  return {
    targetUseCase: isMockExam ? 'online_mock_exam' : 'subject_practice',
    intendedUse,
    subject: cleanString(blueprint.subject),
    syllabusVersion: cleanString(blueprint.syllabusVersion) || null,
    topicId: nullableNumber(blueprint.topicId),
    topicCode: cleanString(blueprint.topicCode) || null,
    gapKey: cleanString(recordFrom(constraintsRecord(blueprint.constraints).targetProfile)?.gapKey) || null,
    mockSourcePaperId: isMockExam ? nullableNumber(mockExamSlot.sourcePaperId) : null,
    mockBlueprintId: isMockExam ? nullableNumber(mockExamSlot.blueprintId) : null,
    mockBlueprintSlotId: isMockExam ? nullableNumber(mockExamSlot.slotId) : null,
    mockSlotNumber: isMockExam ? nullableNumber(mockExamSlot.slotNumber) : null,
    generationMode: baseMode
  };
}

function numberFromDb(value: bigint | number | null | undefined) {
  if (typeof value === 'bigint') return Number(value);
  return typeof value === 'number' && Number.isFinite(value) ? value : 0;
}

function optionalCleanString(value: unknown) {
  const text = cleanString(value, '');
  return text || null;
}

function sha256Text(value: unknown) {
  return createHash('sha256').update(JSON.stringify(value ?? null)).digest('hex');
}

function defaultSourceUsagePolicy(value: unknown) {
  const input = recordFrom(value) ?? {};
  return {
    allowStyleExtraction: input.allowStyleExtraction !== false,
    allowQuestionDisplay: input.allowQuestionDisplay !== false,
    allowPromptRawText: input.allowPromptRawText !== false,
    allowSimilarityCheck: input.allowSimilarityCheck !== false,
    ...(recordFrom(input.sourceCompleteness) ? { sourceCompleteness: input.sourceCompleteness } : {}),
    ...(typeof input.notes === 'string' && input.notes.trim() ? { notes: input.notes.trim() } : {})
  };
}

function sourceDocumentCompletenessMetadata(
  documentInput: Record<string, unknown>,
  questionsInput: unknown[]
): SourceDocumentCompletenessMetadata {
  const excludedQuestions = Array.isArray(documentInput.excludedQuestions)
    ? documentInput.excludedQuestions
        .map((item) => {
          const record = recordFrom(item) ?? {};
          const questionNumber = cleanString(record.questionNumber ?? record.number ?? record.q);
          if (!questionNumber) return null;
          return {
            questionNumber,
            reason: cleanString(record.reason, 'source question excluded')
          };
        })
        .filter((item): item is { questionNumber: string; reason: string } => Boolean(item))
    : [];
  const actualQuestionCount = questionsInput.length;
  const explicitExpected = Number(
    documentInput.expectedQuestionCount
      ?? documentInput.totalQuestionCount
      ?? documentInput.questionCount
      ?? documentInput.expectedQuestions
  );
  const expectedQuestionCount = Number.isInteger(explicitExpected) && explicitExpected > 0 && explicitExpected <= 300
    ? explicitExpected
    : excludedQuestions.length > 0
      ? actualQuestionCount + excludedQuestions.length
      : actualQuestionCount;
  const questionNumbers = new Set(
    questionsInput
      .map((item, index) => cleanString(recordFrom(item)?.questionNumber, String(index + 1)))
      .filter(Boolean)
  );
  const excludedNumbers = new Set(excludedQuestions.map((item) => item.questionNumber));
  const missingQuestionNumbers: string[] = [];
  if (Number.isInteger(expectedQuestionCount) && expectedQuestionCount > 0 && expectedQuestionCount <= 120) {
    for (let index = 1; index <= expectedQuestionCount; index += 1) {
      const questionNumber = String(index);
      if (!questionNumbers.has(questionNumber) && !excludedNumbers.has(questionNumber)) missingQuestionNumbers.push(questionNumber);
    }
  }
  const accountedQuestionCount = actualQuestionCount + excludedQuestions.length;
  const completenessRatio = expectedQuestionCount > 0
    ? Math.min(1, accountedQuestionCount / expectedQuestionCount)
    : null;
  const completenessStatus = expectedQuestionCount > accountedQuestionCount || missingQuestionNumbers.length > 0
    ? 'partial'
    : excludedQuestions.length > 0
      ? 'partial_with_exclusions'
      : 'complete';
  const note = completenessStatus === 'complete'
    ? '源卷题目已按导入范围完整入库。'
    : completenessStatus === 'partial_with_exclusions'
      ? '源卷存在已说明的缺题/无效题；这些题不进入画像样本，其余题正常参与画像生成。'
      : '源卷存在未说明缺题；不阻断画像生成，但建议核对源文件。';
  return {
    expectedQuestionCount,
    actualQuestionCount,
    excludedQuestionCount: excludedQuestions.length,
    excludedQuestions,
    missingQuestionNumbers,
    completenessRatio,
    completenessStatus,
    note
  };
}

function sourceQuestionSignalText(source: unknown) {
  const record = recordFrom(source) ?? {};
  const options = Array.isArray(record.options)
    ? record.options.map((item) => cleanString(recordFrom(item)?.text ?? item)).join(' ')
    : '';
  return [
    cleanString(record.promptText ?? record.prompt),
    options,
    cleanString(record.explanation)
  ].join(' ').toLowerCase();
}

function inferredSourceAnalysis(source: unknown) {
  const text = sourceQuestionSignalText(source);
  const hasFormula = /[=<>≤≥+\-*/^√]|\\frac|\\sqrt|sin|cos|tan|log|ln|mol|ph|j\b|n\b|v\b|a\b|f\b|p\b/.test(text);
  const hasNumbers = /\d/.test(text);
  const hasDiagram = /图|image|diagram|graph|曲线|坐标|函数图像|示意图/.test(text);
  const hasTable = /表|table|数据|dataset/.test(text);
  const asksCalculation = /求|计算|solve|calculate|find|determine|多少|几|值|结果|浓度|体积|速度|加速度|概率|方程/.test(text);
  const asksJudgement = /正确|不正确|错误|符合|不符合|which|statement|best|判断|原因/.test(text);
  const optionCount = Array.isArray(recordFrom(source)?.options) ? (recordFrom(source)?.options as unknown[]).length : 0;
  const reasoningSteps = asksCalculation && hasFormula && hasNumbers ? 3 : hasFormula || hasDiagram ? 2 : 1;
  const calculationLoad = asksCalculation && hasFormula && hasNumbers ? 'medium' : asksCalculation && hasNumbers ? 'light' : 'none';
  const difficulty = reasoningSteps >= 3 ? 'medium' : 'basic';
  return {
    cognitiveSkill: asksCalculation ? 'standard_application' : asksJudgement ? 'concept_discrimination' : 'concept_identification',
    difficulty,
    difficultyEvidence: asksCalculation && hasFormula ? 'inferred_from_formula_and_calculation_signals' : 'inferred_from_stem_signals',
    questionForm: hasDiagram ? 'diagram_interpretation' : asksCalculation ? 'calculation_application' : asksJudgement ? 'concept_judgement' : 'concept_check',
    stemPattern: {
      hasScenario: /实验|情境|实际|应用|experiment|scenario|given|已知/.test(text),
      hasFormula,
      hasDiagram,
      hasTable
    },
    reasoningSteps,
    calculationLoad,
    optionPattern: {
      optionStyle: optionCount >= 4 ? 'four_option_single_choice' : optionCount > 0 ? `${optionCount}_option_single_choice` : 'unknown',
      distractorTypes: asksCalculation ? ['calculation_error', 'condition_misread'] : ['concept_confusion'],
      commonMisconceptions: []
    },
    styleNotes: ['rule_inferred'],
    doNotCopySignals: []
  };
}

function sourceAnalysisFromQuestion(value: unknown, source?: unknown) {
  const normalized = normalizeSourceQuestionAnalysis({ analysis: value, sourceQuestion: recordFrom(source) ?? {} });
  return {
    schemaVersion: 'source-question-analysis-v2',
    profile: normalized,
    parser: {
      provider: normalized.styleNotes.includes('rule_inferred') ? 'rule' : 'hybrid',
      parsedAt: new Date().toISOString()
    },
    cognitiveSkill: normalized.cognitiveSkill,
    difficulty: normalized.difficultyBand === 'unknown' ? 'basic' : normalized.difficultyBand,
    difficultyEvidence: normalized.difficultyEvidence,
    questionForm: normalized.questionForm,
    readingLoad: normalized.readingLoad,
    stemPattern: {
      ...normalized.stemPattern,
      length: normalized.readingLoad
    },
    reasoningSteps: normalized.reasoningStepCount ?? 1,
    calculationLoad: normalized.calculationLoad === 'unknown' ? 'none' : normalized.calculationLoad,
    estimatedTimeSeconds: normalized.estimatedTimeSeconds,
    optionPattern: normalized.optionPattern,
    loadEvidence: normalized.loadEvidence,
    styleNotes: normalized.styleNotes,
    doNotCopySignals: normalized.similarityRiskSignals,
    profileConfidence: normalized.profileConfidence,
    profileIssues: normalized.profileIssues
  };
}

function incrementCounter(map: Map<string, number>, key: unknown) {
  const next = cleanString(key);
  if (!next || ['unknown', 'unk', 'n/a', 'na', 'none', 'null', 'undefined', '未识别', '未知', '无'].includes(next.toLowerCase())) return;
  map.set(next, (map.get(next) ?? 0) + 1);
}

function topWeighted(map: Map<string, number>, total: number) {
  return Array.from(map.entries())
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([key, count]) => ({ key, count, weight: total > 0 ? Number((count / total).toFixed(3)) : 0 }));
}

function incrementVisualizationCounter(map: Map<string, number>, key: unknown, fallback = 'unknown') {
  const next = cleanString(key, fallback) || fallback;
  map.set(next, (map.get(next) ?? 0) + 1);
}

function visualizationDistribution(map: Map<string, number>, total: number, labels: Map<string, string> = new Map(), limit = 12) {
  return Array.from(map.entries())
    .sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]))
    .slice(0, limit)
    .map(([key, count]) => ({
      key,
      label: labels.get(key) ?? key,
      count,
      ratio: total > 0 ? Number((count / total).toFixed(4)) : 0
    }));
}

function weightedKeys(value: unknown, fallback: string[] = []) {
  if (Array.isArray(value)) {
    const keys = value
      .map((item) => cleanString(recordFrom(item)?.key ?? item))
      .filter(Boolean);
    return keys.length ? Array.from(new Set(keys)) : fallback;
  }
  const record = recordFrom(value) ?? {};
  const keys = Object.entries(record)
    .sort((left, right) => Number(right[1] ?? 0) - Number(left[1] ?? 0) || left[0].localeCompare(right[0]))
    .map(([key]) => cleanString(key))
    .filter(Boolean);
  return keys.length ? keys : fallback;
}

function normalizedDifficultyCounts(value: unknown) {
  const source = recordFrom(value) ?? {};
  const counts = new Map<string, number>();
  for (const [key, rawCount] of Object.entries(source)) {
    const difficulty = normalizeDifficultyKey(key);
    if (!isCanonicalDifficultyKey(difficulty)) continue;
    const count = Number(rawCount ?? 0);
    if (!Number.isFinite(count) || count <= 0) continue;
    counts.set(difficulty, (counts.get(difficulty) ?? 0) + count);
  }
  return counts;
}

function difficultyWeightEntries(value: unknown, allowedDifficulties: string[]) {
  const allowed = new Set(allowedDifficulties.map(normalizeDifficultyKey).filter(isCanonicalDifficultyKey));
  const weights = new Map<string, number>();
  const addWeight = (key: unknown, rawWeight: unknown) => {
    const difficulty = normalizeDifficultyKey(key);
    if (!isCanonicalDifficultyKey(difficulty) || !allowed.has(difficulty)) return;
    const weight = Number(rawWeight ?? 0);
    weights.set(difficulty, (weights.get(difficulty) ?? 0) + (Number.isFinite(weight) && weight > 0 ? weight : 1));
  };
  const record = recordFrom(value);
  if (record) {
    for (const [key, weight] of Object.entries(record)) addWeight(key, weight);
  } else if (Array.isArray(value)) {
    for (const item of value) addWeight(recordFrom(item)?.key ?? item, recordFrom(item)?.weight ?? 1);
  }
  if (!weights.size) {
    for (const difficulty of allowed) weights.set(difficulty, 1);
  }
  return Array.from(weights.entries())
    .map(([difficulty, weight]) => ({ difficulty, weight }))
    .sort((left, right) => right.weight - left.weight || difficultyGenerationPriority(left.difficulty) - difficultyGenerationPriority(right.difficulty));
}

function allocateDifficultyTargets(totalCount: number, entries: Array<{ difficulty: string; weight: number }>) {
  const count = Math.max(0, Math.floor(totalCount));
  const active = entries.filter((entry) => isCanonicalDifficultyKey(entry.difficulty) && entry.weight > 0);
  if (count <= 0 || !active.length) return new Map<string, number>();
  const totalWeight = active.reduce((sum, entry) => sum + entry.weight, 0) || active.length;
  const quotas = active.map((entry) => {
    const raw = count * entry.weight / totalWeight;
    return {
      difficulty: entry.difficulty,
      raw,
      target: Math.floor(raw),
      remainder: raw - Math.floor(raw)
    };
  });
  if (count >= quotas.length) {
    for (const quota of quotas) {
      if (quota.target <= 0) quota.target = 1;
    }
  }
  let assigned = quotas.reduce((sum, quota) => sum + quota.target, 0);
  while (assigned > count) {
    const candidate = quotas
      .filter((quota) => quota.target > 0)
      .sort((left, right) => (left.raw - left.target) - (right.raw - right.target) || left.raw - right.raw)[0];
    if (!candidate) break;
    candidate.target -= 1;
    assigned -= 1;
  }
  while (assigned < count) {
    const candidate = quotas
      .sort((left, right) => (right.raw - right.target) - (left.raw - left.target) || right.raw - left.raw)[0];
    if (!candidate) break;
    candidate.target += 1;
    assigned += 1;
  }
  return new Map(quotas.filter((quota) => quota.target > 0).map((quota) => [quota.difficulty, quota.target]));
}

function weightedTargetEntries(value: unknown) {
  const record = recordFrom(value) ?? {};
  return Object.entries(record)
    .map(([key, rawWeight]) => {
      const weight = Number(rawWeight ?? 0);
      return { key: cleanString(key), weight: Number.isFinite(weight) && weight > 0 ? weight : 0 };
    })
    .filter((entry) => entry.key && entry.weight > 0);
}

function allocateWeightedTargets(totalCount: number, value: unknown) {
  const count = Math.max(0, Math.floor(totalCount));
  const active = weightedTargetEntries(value);
  if (count <= 0 || !active.length) return {};
  const totalWeight = active.reduce((sum, entry) => sum + entry.weight, 0) || active.length;
  const quotas = active.map((entry) => {
    const raw = count * entry.weight / totalWeight;
    return {
      key: entry.key,
      raw,
      target: Math.floor(raw),
      remainder: raw - Math.floor(raw)
    };
  });
  if (count >= quotas.length) {
    for (const quota of quotas) {
      if (quota.target <= 0) quota.target = 1;
    }
  }
  let assigned = quotas.reduce((sum, quota) => sum + quota.target, 0);
  while (assigned > count) {
    const candidate = quotas
      .filter((quota) => quota.target > 0)
      .sort((left, right) => (left.raw - left.target) - (right.raw - right.target) || left.raw - right.raw)[0];
    if (!candidate) break;
    candidate.target -= 1;
    assigned -= 1;
  }
  while (assigned < count) {
    const candidate = quotas
      .sort((left, right) => (right.raw - right.target) - (left.raw - left.target) || right.raw - left.raw)[0];
    if (!candidate) break;
    candidate.target += 1;
    assigned += 1;
  }
  return Object.fromEntries(
    quotas
      .filter((quota) => quota.target > 0)
      .sort((left, right) => right.target - left.target || left.key.localeCompare(right.key))
      .map((quota) => [quota.key, quota.target])
  );
}

function normalizedPaperTargetsFromProfile(profile: Record<string, unknown>, targetCount = 48) {
  const normalizedTargetCount = Math.max(1, Math.floor(targetCount));
  return {
    schemaVersion: 'csca-normalized-paper-target-v1',
    targetCount: normalizedTargetCount,
    source: 'exam_series_profile',
    rounding: 'largest_remainder_with_minimum_one_for_observed_keys',
    distributions: {
      difficulty: allocateWeightedTargets(normalizedTargetCount, profile.difficultyDistribution),
      questionForm: allocateWeightedTargets(normalizedTargetCount, profile.questionFormDistribution),
      cognitiveSkill: allocateWeightedTargets(normalizedTargetCount, profile.cognitiveSkillDistribution),
      readingLoad: allocateWeightedTargets(normalizedTargetCount, profile.readingLoadDistribution),
      calculationLoad: allocateWeightedTargets(normalizedTargetCount, profile.calculationLoadDistribution),
      answer: allocateWeightedTargets(normalizedTargetCount, profile.answerDistribution)
    }
  };
}

function subjectPracticeProductionDifficultyPlan(input: {
  targetCount: number;
  difficultyRange: unknown;
  bridgeDifficultyCounts: unknown;
}) {
  const allowedDifficulties = blueprintDifficultiesFromRange(input.difficultyRange);
  const entries = allowedDifficulties.map((difficulty) => ({
    difficulty,
    weight: SUBJECT_PRACTICE_PRODUCTION_DIFFICULTY_WEIGHTS[difficulty as typeof CSCA_CANONICAL_DIFFICULTY_KEYS[number]] ?? 1
  }));
  const targets = allocateDifficultyTargets(input.targetCount, entries);
  const currentByDifficulty = normalizedDifficultyCounts(input.bridgeDifficultyCounts);
  return Array.from(targets.entries())
    .map(([difficulty, targetCount]) => {
      const currentCount = currentByDifficulty.get(difficulty) ?? 0;
      const neededCount = Math.max(0, targetCount - currentCount);
      return {
        difficultyBand: difficulty,
        targetCount,
        currentCount,
        neededCount,
        shortageRatio: targetCount > 0 ? neededCount / targetCount : 0
      };
    })
    .sort((left, right) => (
      CSCA_CANONICAL_DIFFICULTY_KEYS.indexOf(left.difficultyBand as typeof CSCA_CANONICAL_DIFFICULTY_KEYS[number])
      - CSCA_CANONICAL_DIFFICULTY_KEYS.indexOf(right.difficultyBand as typeof CSCA_CANONICAL_DIFFICULTY_KEYS[number])
    ));
}

function subjectPracticeProductionCandidateLimit(input: { targetCount: number; neededCount?: number }) {
  const targetCount = Math.max(1, Number(input.targetCount) || 1);
  const neededCount = Math.max(1, Number(input.neededCount ?? targetCount) || 1);
  return Math.min(120, Math.max(12, neededCount * 6, Math.ceil(targetCount * 2)));
}

function subjectPracticeProductionSoftCandidateBudget(input: {
  targetCount: number;
  publishedCount: number;
  candidateLimit: number;
}) {
  const targetCount = Math.max(1, Number(input.targetCount) || 1);
  const publishedCount = Math.max(0, Number(input.publishedCount) || 0);
  const candidateLimit = Math.max(1, Number(input.candidateLimit) || subjectPracticeProductionCandidateLimit({
    targetCount,
    neededCount: Math.max(1, targetCount - publishedCount)
  }));
  const remainingGap = Math.max(0, targetCount - publishedCount);
  if (remainingGap <= 0) return 0;
  const buffer = remainingGap <= 1 ? 1 : remainingGap <= 3 ? 2 : 3;
  return Math.min(candidateLimit, Math.max(1, remainingGap + buffer));
}

const SUBJECT_PRACTICE_PRO_GENERATION_TIER = 'pro';
const SUBJECT_PRACTICE_PRO_ESCALATION_REASON = 'candidate_limit_reached';
const SUBJECT_PRACTICE_PRO_EXHAUSTED_REASON = 'pro_candidate_limit_reached';

function subjectPracticeProductionProEscalationEnabled() {
  return process.env.CSCA_SUBJECT_PRACTICE_PRO_ESCALATION_ENABLED !== 'false';
}

function subjectPracticeProductionProCandidateLimit(input: { targetCount: number; neededCount?: number }) {
  const standardLimit = subjectPracticeProductionCandidateLimit(input);
  return Math.min(240, Math.max(60, standardLimit * 3));
}

function subjectPracticeProductionProfileRecord(profile: unknown) {
  return { ...(recordFrom(profile) ?? {}) };
}

function subjectPracticeGenerationTierConstraints(input: { generationTier?: string | null; preferredModelTier?: string | null }) {
  const generationTier = cleanString(input.generationTier);
  if (!generationTier) return {};
  const preferredModelTier = cleanString(input.preferredModelTier, generationTier);
  return {
    subjectPracticeGenerationTier: generationTier,
    generationTier,
    modelTier: preferredModelTier,
    preferredModelTier
  };
}

function isSubjectPracticeProductionProProfile(profile: unknown) {
  const record = recordFrom(profile);
  const tier = cleanString(record?.subjectPracticeGenerationTier || record?.generationTier || record?.modelTier || record?.preferredModelTier);
  return tier === SUBJECT_PRACTICE_PRO_GENERATION_TIER;
}

function subjectPracticeProductionProProfile(profile: unknown, input: {
  reasonCode: string;
  candidateLimit: number;
  escalatedAt?: Date;
}) {
  const escalatedAt = input.escalatedAt ?? new Date();
  return {
    ...subjectPracticeProductionProfileRecord(profile),
    subjectPracticeGenerationTier: SUBJECT_PRACTICE_PRO_GENERATION_TIER,
    generationTier: SUBJECT_PRACTICE_PRO_GENERATION_TIER,
    modelTier: SUBJECT_PRACTICE_PRO_GENERATION_TIER,
    preferredModelTier: SUBJECT_PRACTICE_PRO_GENERATION_TIER,
    subjectPracticeProEscalation: {
      status: 'enabled',
      reasonCode: input.reasonCode,
      candidateLimit: input.candidateLimit,
      escalatedAt: escalatedAt.toISOString()
    }
  };
}

function subjectPracticeProductionIncompleteProfile(profile: unknown, input: {
  reasonCode: string;
  missingCount: number;
  candidateCount: number;
  candidateLimit: number;
  markedAt?: Date;
}) {
  const markedAt = input.markedAt ?? new Date();
  return {
    ...subjectPracticeProductionProfileRecord(profile),
    subjectPracticeIncomplete: {
      status: 'incomplete',
      reasonCode: input.reasonCode,
      missingCount: input.missingCount,
      candidateCount: input.candidateCount,
      candidateLimit: input.candidateLimit,
      markedAt: markedAt.toISOString()
    }
  };
}

function subjectPracticeCellIsTerminalIncomplete(cell: Pick<SubjectPracticeProductionCellRow, 'status' | 'failureCode'>) {
  return cell.status === 'blocked' && cell.failureCode === SUBJECT_PRACTICE_PRO_EXHAUSTED_REASON;
}

function subjectPracticeProductionCellIsDispatchable(cell: Pick<SubjectPracticeProductionCellRow,
  'status' | 'publishedCount' | 'targetCount' | 'failureCode' | 'candidateCount' | 'candidateLimit' | 'runningJobCount'
>) {
  const softCandidateBudget = subjectPracticeProductionSoftCandidateBudget({
    targetCount: cell.targetCount,
    publishedCount: cell.publishedCount,
    candidateLimit: Math.max(1, cell.candidateLimit)
  });
  return ['open', 'running'].includes(cell.status)
    && cell.publishedCount < cell.targetCount
    && !cell.failureCode
    && cell.runningJobCount === 0
    && cell.runningJobCount < softCandidateBudget;
}

const SUBJECT_PRACTICE_AUTO_DISABLED_BLOCK_REASONS = [
  'subject_auto_production_disabled',
  'global_auto_production_disabled'
] as const;

const SUBJECT_PRACTICE_RECOVERABLE_READINESS_BLOCK_REASONS = [
  'source_profile_missing',
  'source_profile_incomplete',
  'source_profile_stale',
  'generation_profile_missing',
  'generation_profile_stale',
  'generation_profile_source_snapshot_stale',
  'generation_profile_syllabus_snapshot_stale'
] as const;

function isSubjectPracticeAutoDisabledBlockReason(value: unknown) {
  return SUBJECT_PRACTICE_AUTO_DISABLED_BLOCK_REASONS.includes(cleanString(value) as typeof SUBJECT_PRACTICE_AUTO_DISABLED_BLOCK_REASONS[number]);
}

function isSubjectPracticeRecoverableReadinessBlockReason(value: unknown) {
  return SUBJECT_PRACTICE_RECOVERABLE_READINESS_BLOCK_REASONS.includes(cleanString(value) as typeof SUBJECT_PRACTICE_RECOVERABLE_READINESS_BLOCK_REASONS[number]);
}

function isSubjectPracticeManualResumeBlockReason(value: unknown) {
  const reason = cleanString(value);
  return isSubjectPracticeAutoDisabledBlockReason(reason) || reason === 'no_progress';
}

function isSubjectPracticeTransientProductionBlockReason(value: unknown) {
  const reason = cleanString(value);
  return reason === 'cell_blocked' || reason === 'no_dispatchable_cell';
}

function subjectPracticeRunLineageMatchesReadyProfile(runLineage: unknown, readiness: SubjectPracticeGenerationReadiness) {
  if (!readiness.ready) return false;
  const stableRunLineage = generationProfileStableSnapshotLineage(recordFrom(runLineage));
  if (!stableRunLineage) return true;
  const stableReadyLineage = generationProfileStableSnapshotLineage({
    generationProfileId: readiness.activeGenerationProfileId,
    sourceSnapshotHash: readiness.activeGenerationSourceSnapshotHash,
    syllabusSnapshotHash: readiness.activeGenerationSyllabusSnapshotHash
  });
  return !generationProfileLineageIsStale(
    generationProfileLineageFromMetadata(stableRunLineage),
    stableReadyLineage ?? {}
  );
}

function subjectPracticeManualResumeLease(value: unknown) {
  const result = recordFrom(value) ?? {};
  return recordFrom(result.manualResume);
}

function subjectPracticeRunHasManualResumeLease(run: Pick<SubjectPracticeProductionRunRow, 'result'>) {
  const lease = subjectPracticeManualResumeLease(run.result);
  return cleanString(lease?.status) === 'active';
}

function meaningfulWeightedKeys(value: unknown, fallback: string[] = [], blocked: string[] = ['unknown']) {
  const blockedSet = new Set(blocked.map((item) => item.toLowerCase()));
  const keys = weightedKeys(value, fallback)
    .map((item) => cleanString(item))
    .filter((item) => item && !blockedSet.has(item.toLowerCase()));
  return keys.length ? keys : fallback;
}

function subjectPracticeGapKey(input: {
  topicId: number;
  questionForm: string;
  cognitiveSkill: string;
  difficultyBand: string;
  readingLoad: string;
  calculationLoad: string;
}) {
  const segment = (value: unknown, fallback: string) => cleanString(value, fallback)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    || fallback;
  return [
    `topic_${input.topicId}`,
    segment(input.questionForm, 'unknown'),
    segment(input.cognitiveSkill, 'unknown'),
    segment(input.difficultyBand, 'unknown'),
    segment(input.readingLoad, 'unknown'),
    segment(input.calculationLoad, 'unknown')
  ].join(':');
}

function deriveTopicQuestionGap(input: {
  row: TopicQuestionBankHealthRow;
  expectedBlueprintCount: number;
  styleProfile: ReturnType<typeof mapStyleProfile> | null;
}): TopicQuestionGap {
  const targetCount = Math.max(input.expectedBlueprintCount * 3, 6);
  const currentCount = Number(input.row.bridgeQuestionCount ?? 0);
  if (!input.styleProfile) {
    return { topicId: input.row.topicId, currentCount, targetCount, difficultyPlan: [], gaps: [] };
  }
  const profile = recordFrom(input.styleProfile.profile) ?? {};
  const questionForms = meaningfulWeightedKeys(profile.questionFormDistribution, meaningfulWeightedKeys(profile.commonQuestionForms));
  const cognitiveSkills = meaningfulWeightedKeys(profile.cognitiveSkillDistribution, meaningfulWeightedKeys(profile.commonCognitiveSkills), ['unknown']);
  const readingLoads = meaningfulWeightedKeys(profile.readingLoadDistribution, meaningfulWeightedKeys(profile.commonReadingLoads), ['unknown']);
  const calculationLoads = meaningfulWeightedKeys(profile.calculationLoadDistribution, meaningfulWeightedKeys(profile.commonCalculationLoads), ['unknown']);
  const allowedDifficulties = blueprintDifficultiesFromRange(input.row.difficultyRange);
  const difficultyTargets = allocateDifficultyTargets(targetCount, difficultyWeightEntries(profile.difficultyDistribution, allowedDifficulties));
  const currentByDifficulty = normalizedDifficultyCounts(input.row.bridgeDifficultyCounts);
  const difficultyPlan = Array.from(difficultyTargets.entries())
    .map(([difficulty, difficultyTarget]) => {
      const currentDifficultyCount = currentByDifficulty.get(difficulty) ?? 0;
      const neededCount = Math.max(0, difficultyTarget - currentDifficultyCount);
      return {
        difficultyBand: difficulty,
        targetCount: difficultyTarget,
        currentCount: currentDifficultyCount,
        neededCount,
        shortageRatio: difficultyTarget > 0 ? neededCount / difficultyTarget : 0
      };
    })
    .sort((left, right) => right.shortageRatio - left.shortageRatio
      || difficultyGenerationPriority(left.difficultyBand) - difficultyGenerationPriority(right.difficultyBand)
      || right.neededCount - left.neededCount);
  const profileSlots = difficultyPlan
    .map((plan, index) => {
      const profileSlice = {
        questionForm: questionForms[index % Math.max(1, questionForms.length)] ?? questionForms[0] ?? 'unknown',
        cognitiveSkill: cognitiveSkills[index % Math.max(1, cognitiveSkills.length)] ?? cognitiveSkills[0] ?? 'unknown',
        difficultyBand: plan.difficultyBand,
        readingLoad: readingLoads[index % Math.max(1, readingLoads.length)] ?? readingLoads[0] ?? 'unknown',
        calculationLoad: calculationLoads[index % Math.max(1, calculationLoads.length)] ?? calculationLoads[0] ?? 'unknown'
      };
      return {
        gapKey: subjectPracticeGapKey({ topicId: input.row.topicId, ...profileSlice }),
        ...profileSlice,
        neededCount: plan.neededCount,
        reason: 'coverage' as const
      };
    })
  const gaps = profileSlots.filter((item) => item.neededCount > 0);
  return {
    topicId: input.row.topicId,
    currentCount,
    targetCount,
    difficultyPlan,
    gaps,
    profileSlots
  };
}

function firstWeightedKey(value: unknown, fallback = '') {
  const keys = meaningfulWeightedKeys(value, fallback ? [fallback] : []);
  return keys[0] ?? fallback;
}

const TARGET_PROFILE_UNKNOWN_VALUES = new Set(['', 'unknown', 'unk', 'n/a', 'na', 'none', 'null', 'undefined', '未识别', '未知', '无']);
const TARGET_PROFILE_CALCULATION_LOAD_VALUES = new Set(['none', 'light', 'medium', 'heavy']);

function targetProfileValue(value: unknown) {
  const text = cleanString(value);
  return TARGET_PROFILE_UNKNOWN_VALUES.has(text.toLowerCase()) ? '' : text;
}

function targetProfileFieldValue(field: string, value: unknown) {
  const text = cleanString(value);
  const normalized = normalizeLoadKey(text);
  if (field === 'calculationLoad' && TARGET_PROFILE_CALCULATION_LOAD_VALUES.has(normalized)) {
    return normalized;
  }
  return targetProfileValue(value);
}

function calculationLoadFromGapKey(value: unknown): string {
  const parts = cleanString(value).split(':');
  const normalized = normalizeLoadKey(parts[parts.length - 1]);
  return TARGET_PROFILE_CALCULATION_LOAD_VALUES.has(normalized) ? normalized : '';
}

function difficultyBandFromSubjectPracticeGapKey(value: unknown): string {
  const parts = cleanString(value).split(':');
  const difficulty = normalizeDifficultyKey(parts[3]);
  return isCanonicalDifficultyKey(difficulty) ? difficulty : '';
}

function targetProfileCalculationLoadValue(value: unknown, profileRecord?: unknown): string {
  const normalized = normalizeLoadKey(value);
  if (TARGET_PROFILE_CALCULATION_LOAD_VALUES.has(normalized)) return normalized;
  const record = recordFrom(profileRecord);
  if (!record) return '';
  const fromGapKey = calculationLoadFromGapKey(record?.gapKey);
  if (fromGapKey) return fromGapKey;
  const normalization = recordFrom(record?.subjectPracticeProfileNormalization);
  const original = recordFrom(normalization?.original);
  const fromOriginalValue: string = targetProfileCalculationLoadValue(original?.calculationLoad, original);
  if (fromOriginalValue) return fromOriginalValue;
  return calculationLoadFromGapKey(original?.gapKey);
}

function targetProfileIncompleteReasons(value: unknown) {
  const record = recordFrom(value);
  if (!record) return ['target_profile_missing'];
  const requiredFields = ['questionForm', 'cognitiveSkill', 'difficultyBand', 'readingLoad', 'calculationLoad'];
  const reasons = requiredFields
    .filter((field) => field === 'calculationLoad'
      ? !targetProfileCalculationLoadValue(record[field], record)
      : !targetProfileFieldValue(field, record[field]))
    .map((field) => `${field}_missing_or_unknown`);
  return Array.from(new Set(reasons));
}

function topicQuestionGapIncompleteReasons(questionGap: TopicQuestionGap) {
  return Array.from(new Set(
    questionGap.gaps.flatMap((gap) => targetProfileIncompleteReasons(gap))
  ));
}

function targetProfileFromStyleProfile(styleProfile: ReturnType<typeof mapStyleProfile> | null, topicIdValue?: unknown): SubjectTrainingTargetProfile | null {
  if (!styleProfile) return null;
  const profile = recordFrom(styleProfile.profile) ?? {};
  const optionPatterns = recordFrom(profile.optionPatterns) ?? {};
  const estimatedTime = recordFrom(profile.estimatedTimeSeconds) ?? {};
  const questionForm = firstWeightedKey(profile.questionFormDistribution, firstWeightedKey(profile.commonQuestionForms));
  const cognitiveSkill = firstWeightedKey(profile.cognitiveSkillDistribution, firstWeightedKey(profile.commonCognitiveSkills));
  const difficultyBand = normalizeDifficultyKey(firstWeightedKey(profile.difficultyDistribution));
  const readingLoad = firstWeightedKey(profile.readingLoadDistribution);
  const calculationLoad = firstWeightedKey(profile.calculationLoadDistribution);
  const topicId = Number(topicIdValue) || Number(styleProfile.scopeId) || 0;
  return {
    gapKey: subjectPracticeGapKey({
      topicId,
      questionForm,
      cognitiveSkill,
      difficultyBand,
      readingLoad,
      calculationLoad
    }),
    questionForm,
    cognitiveSkill,
    difficultyBand,
    readingLoad,
    calculationLoad,
    estimatedTimeSeconds: typeof estimatedTime.p50 === 'number' ? estimatedTime.p50 : null,
    distractorTypes: weightedKeys(optionPatterns.commonDistractorTypes, []),
    commonMisconceptions: weightedKeys(optionPatterns.commonMisconceptions, []),
    neededCount: 1,
    reason: 'coverage',
    source: 'style_profile'
  };
}

function sanitizeTargetProfile(value: unknown): SubjectTrainingTargetProfile | null {
  const record = recordFrom(value);
  if (!record || Object.keys(record).length === 0) return null;
  const generationStrategy = recordFrom(record.generationStrategy);
  const questionForm = targetProfileValue(record.questionForm);
  const cognitiveSkill = targetProfileValue(record.cognitiveSkill);
  const rawDifficultyBand = targetProfileValue(record.difficultyBand);
  const difficultyBand = rawDifficultyBand ? normalizeDifficultyKey(rawDifficultyBand) : '';
  const readingLoad = targetProfileValue(record.readingLoad);
  const calculationLoad = targetProfileCalculationLoadValue(record.calculationLoad, record);
  const estimatedTimeSeconds = Number(record.estimatedTimeSeconds);
  const slotNumber = Number(record.slotNumber);
  return {
    gapKey: cleanString(record.gapKey) || subjectPracticeGapKey({
      topicId: Number(record.topicId) || 0,
      questionForm,
      cognitiveSkill,
      difficultyBand,
      readingLoad,
      calculationLoad
    }),
    ...(cleanString(record.module) ? { module: cleanString(record.module) } : {}),
    ...(Number.isFinite(slotNumber) && slotNumber > 0 ? { slotNumber: Math.round(slotNumber) } : {}),
    questionForm,
    cognitiveSkill,
    difficultyBand,
    readingLoad,
    calculationLoad,
    estimatedTimeSeconds: Number.isFinite(estimatedTimeSeconds) && estimatedTimeSeconds > 0 ? Math.round(estimatedTimeSeconds) : null,
    distractorTypes: optionalStringArray(record.distractorTypes),
    commonMisconceptions: optionalStringArray(record.commonMisconceptions),
    neededCount: Math.max(1, Number(record.neededCount ?? 1) || 1),
    reason: ['coverage', 'low_quality_existing', 'student_weakness', 'mock_candidate_pool'].includes(cleanString(record.reason))
      ? cleanString(record.reason) as SubjectTrainingTargetProfile['reason']
      : 'coverage',
    ...(generationStrategy
      ? {
        generationStrategy: {
          schemaVersion: cleanString(generationStrategy.schemaVersion, 'mock-exam-generation-strategy-v1'),
          source: cleanString(generationStrategy.source),
          topicFamily: cleanString(generationStrategy.topicFamily),
          requiredStemPattern: cleanString(generationStrategy.requiredStemPattern),
          requiredStemPatternInstruction: cleanString(generationStrategy.requiredStemPatternInstruction),
          allowedStemPatterns: optionalStringArray(generationStrategy.allowedStemPatterns),
          bannedStemPatterns: optionalStringArray(generationStrategy.bannedStemPatterns),
          reviewerEvidenceTargets: optionalStringArray(generationStrategy.reviewerEvidenceTargets),
          diversityAxes: optionalStringArray(generationStrategy.diversityAxes),
          minimumDiversityAxesPerRetry: Number(generationStrategy.minimumDiversityAxesPerRetry) || undefined,
          adjustments: optionalStringArray(generationStrategy.adjustments),
          promptChecklist: optionalStringArray(generationStrategy.promptChecklist),
          normalizedAt: cleanString(generationStrategy.normalizedAt),
          replannedAt: cleanString(generationStrategy.replannedAt),
          replanAttempt: Number(generationStrategy.replanAttempt) || undefined,
          replanReason: cleanString(generationStrategy.replanReason)
        }
      }
      : {}),
    source: ['topic_question_gap', 'style_profile', 'request'].includes(cleanString(record.source))
      ? cleanString(record.source) as SubjectTrainingTargetProfile['source']
      : 'request'
  };
}

function targetProfileForBlueprint(
  blueprint: BlueprintRow,
  styleProfile: ReturnType<typeof mapStyleProfile> | null,
  requested?: unknown
) {
  const explicit = sanitizeTargetProfile(requested);
  if (explicit) return targetProfileAlignedToBlueprint(blueprint, { ...explicit, source: explicit.source ?? 'request' });
  const existing = sanitizeTargetProfile(constraintsRecord(blueprint.constraints).targetProfile);
  if (existing) return targetProfileAlignedToBlueprint(blueprint, existing);
  return targetProfileAlignedToBlueprint(blueprint, targetProfileFromStyleProfile(styleProfile, blueprint.topicId));
}

function targetProfileAlignedToBlueprint(
  blueprint: Pick<BlueprintRow, 'difficulty' | 'topicId'>,
  profile: SubjectTrainingTargetProfile | null
) {
  if (!profile) return null;
  const blueprintDifficulty = normalizeDifficultyKey(blueprint.difficulty);
  if (!isCanonicalDifficultyKey(blueprintDifficulty)) return profile;
  const calculationLoad = subjectPracticeAlignedCalculationLoad(blueprintDifficulty, profile);
  const readingLoad = subjectPracticeAlignedReadingLoad(blueprintDifficulty, profile);
  return {
    ...profile,
    difficultyBand: blueprintDifficulty,
    calculationLoad,
    readingLoad,
    gapKey: subjectPracticeGapKey({
      topicId: Number(blueprint.topicId) || 0,
      questionForm: profile.questionForm,
      cognitiveSkill: profile.cognitiveSkill,
      difficultyBand: blueprintDifficulty,
      readingLoad,
      calculationLoad
    })
  };
}

function subjectIntendedUseForBlueprint(blueprint: Pick<BlueprintRow, 'source' | 'constraints'>) {
  return generationSourceForBlueprint(blueprint, Boolean(constraintsRecord(blueprint.constraints).styleProfile)).sourceKind === 'mock_exam_blueprint_slot'
    ? 'mock_candidate'
    : 'subject_practice';
}

function normalizedSimilarityText(value: unknown) {
  return cleanString(value)
    .toLowerCase()
    .replace(/\\[a-z]+/g, ' ')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function similarityTokens(value: unknown) {
  const text = normalizedSimilarityText(value);
  const tokens = text.split(' ').filter((token) => token.length >= 2);
  const cjkChars = Array.from(text.replace(/[^\p{Script=Han}]/gu, '')).filter(Boolean);
  return new Set([...tokens, ...cjkChars]);
}

function jaccardSimilarity(left: Set<string>, right: Set<string>) {
  if (!left.size || !right.size) return 0;
  let intersection = 0;
  left.forEach((item) => {
    if (right.has(item)) intersection += 1;
  });
  return intersection / (left.size + right.size - intersection);
}

function mapQuestionLedger(row: QuestionLedgerRow, options: { compactMetadata?: boolean } = {}) {
  const exposureCount = numberFromDb(row.exposureCount);
  const attemptCount = numberFromDb(row.attemptCount);
  const correctCount = numberFromDb(row.correctCount);
  const generationMetadata = recordFrom(row.generationMetadata);
  return {
    ...mapQuestion(row, options),
    topicTitle: row.topicTitle,
    topicCode: row.topicCode,
    provider: row.provider || optionalCleanString(generationMetadata?.generator),
    model: row.model || optionalCleanString(generationMetadata?.model),
    generationSourceLabel: generationSourceLabel(row.generationMetadata),
    sourceKind: cleanString(generationMetadata?.sourceKind ?? generationMetadata?.generationSource, 'syllabus'),
    fallbackUsed: questionGenerationUsedFallback(row.generationMetadata),
    versionGovernance: versionGovernanceFromMetadata(row.generationMetadata),
    practiceQuestionStatus: row.practiceQuestionStatus,
    formalAssetUpdatedAt: row.formalAssetUpdatedAt ? row.formalAssetUpdatedAt.toISOString() : null,
    isPracticeReady: row.status === 'approved' && Boolean(row.sourceQuestionId),
    exposureCount,
    attemptCount,
    correctCount,
    accuracy: attemptCount > 0 ? Math.round((correctCount / attemptCount) * 100) : null,
    lastUsedAt: row.lastUsedAt ? row.lastUsedAt.toISOString() : null
  };
}

function mapMisconception(row: MisconceptionRow) {
  return {
    ...row,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString()
  };
}

function mapConceptCard(row: ConceptCardGovernanceRow) {
  return { ...row, createdAt: row.createdAt.toISOString() };
}

function mapSyllabusImport(row: SyllabusImportRow) {
  return {
    ...row,
    appliedAt: row.appliedAt?.toISOString() ?? null,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString()
  };
}

function syllabusPreviewRecord(value: unknown) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
}

function syllabusPreviewItems(value: unknown): Array<Record<string, unknown>> {
  const items = syllabusPreviewRecord(value).items;
  return Array.isArray(items)
    ? items.filter((item): item is Record<string, unknown> => Boolean(item && typeof item === 'object' && !Array.isArray(item)))
    : [];
}

function syllabusPreviewMissingTopics(value: unknown): Array<Record<string, unknown>> {
  const items = syllabusPreviewRecord(value).missingFromFile;
  return Array.isArray(items)
    ? items.filter((item): item is Record<string, unknown> => Boolean(item && typeof item === 'object' && !Array.isArray(item)))
    : [];
}

function syllabusPreviewApplyRecord(value: unknown) {
  return syllabusPreviewRecord(syllabusPreviewRecord(value).apply);
}

function topicSnapshotFromPreview(value: unknown) {
  const record = syllabusPreviewRecord(value);
  if (!record || Object.keys(record).length === 0) return null;
  return {
    code: cleanString(record.code),
    title: cleanString(record.title),
    module: record.module === undefined ? null : cleanString(record.module, '') || null,
    examScope: record.examScope === undefined ? null : cleanString(record.examScope, '') || null,
    syllabusVersion: cleanString(record.syllabusVersion),
    sourceUrl: record.sourceUrl === undefined ? null : cleanString(record.sourceUrl, '') || null,
    sourceLabel: record.sourceLabel === undefined ? null : cleanString(record.sourceLabel, '') || null,
    weight: Number(record.weight ?? 0) || 0,
    allowedQuestionTypes: record.allowedQuestionTypes ?? [],
    difficultyRange: record.difficultyRange ?? [],
    status: cleanString(record.status)
  };
}

function currentTopicMatchesSnapshot(row: SyllabusReversePlanTopicRow | undefined, snapshot: ReturnType<typeof topicSnapshotFromPreview>) {
  if (!row || !snapshot) return false;
  return row.code === snapshot.code
    && row.title === snapshot.title
    && (row.module ?? null) === snapshot.module
    && (row.examScope ?? null) === snapshot.examScope
    && row.syllabusVersion === snapshot.syllabusVersion
    && (row.sourceUrl ?? null) === snapshot.sourceUrl
    && (row.sourceLabel ?? null) === snapshot.sourceLabel
    && row.weight === snapshot.weight
    && row.status === snapshot.status
    && jsonEqual(row.allowedQuestionTypes ?? [], snapshot.allowedQuestionTypes)
    && jsonEqual(row.difficultyRange ?? [], snapshot.difficultyRange);
}

function normalizeTag(value: unknown) {
  return String(value ?? '').trim().toLowerCase();
}

function misconceptionDuplicateKey(value: unknown) {
  return normalizeTag(value).replace(/[^a-z0-9\u4e00-\u9fff]+/g, '');
}

function buildMisconceptionGovernance(rows: MisconceptionRow[]) {
  const activeRows = rows.filter((row) => row.status === 'active');
  const suggestions: Array<{
    issue: 'possible_duplicate' | 'missing_concept_card' | 'orphan_tag';
    severity: 'info' | 'warning';
    misconceptionId: number;
    targetId: number | null;
    label: string;
    targetLabel: string | null;
    subject: string;
    topicId: number | null;
    topicTitle: string | null;
    reason: string;
  }> = [];
  const byKey = new Map<string, MisconceptionRow[]>();
  for (const row of activeRows) {
    const key = `${row.subject}:${row.topicId ?? 'subject'}:${misconceptionDuplicateKey(row.label)}`;
    if (!byKey.has(key)) byKey.set(key, []);
    byKey.get(key)?.push(row);
  }
  for (const group of byKey.values()) {
    if (group.length < 2) continue;
    const target = [...group].sort((a, b) => (b.questionCount + b.conceptCardCount) - (a.questionCount + a.conceptCardCount))[0];
    for (const row of group) {
      if (row.id === target.id) continue;
      suggestions.push({
        issue: 'possible_duplicate',
        severity: 'warning',
        misconceptionId: row.id,
        targetId: target.id,
        label: row.label,
        targetLabel: target.label,
        subject: row.subject,
        topicId: row.topicId,
        topicTitle: row.topicTitle,
        reason: '同一学科/知识点下存在规范化后相同的错因标签。'
      });
    }
  }
  for (const row of activeRows) {
    if (row.questionCount > 0 && row.publishedConceptCardCount === 0) {
      suggestions.push({
        issue: 'missing_concept_card',
        severity: 'warning',
        misconceptionId: row.id,
        targetId: null,
        label: row.label,
        targetLabel: null,
        subject: row.subject,
        topicId: row.topicId,
        topicTitle: row.topicTitle,
        reason: '已有题目选项引用这个错因，但还没有可用概念卡。'
      });
    }
    if (row.questionCount === 0 && row.conceptCardCount === 0) {
      suggestions.push({
        issue: 'orphan_tag',
        severity: 'info',
        misconceptionId: row.id,
        targetId: null,
        label: row.label,
        targetLabel: null,
        subject: row.subject,
        topicId: row.topicId,
        topicTitle: row.topicTitle,
        reason: '这个活跃错因暂时没有题目或概念卡引用。'
      });
    }
  }
  return {
    summary: {
      possibleDuplicateCount: suggestions.filter((item) => item.issue === 'possible_duplicate').length,
      missingConceptCardCount: suggestions.filter((item) => item.issue === 'missing_concept_card').length,
      orphanTagCount: suggestions.filter((item) => item.issue === 'orphan_tag').length,
      totalActionable: suggestions.length
    },
    suggestions: suggestions.slice(0, 20)
  };
}

export function replaceMisconceptionTags(value: unknown, sourceTags: Set<string>, targetLabel: string) {
  if (!Array.isArray(value)) return { optionMetadata: value, changed: false, changedOptions: 0 };
  let changed = false;
  let changedOptions = 0;
  const optionMetadata = value.map((item) => {
    if (!item || typeof item !== 'object' || Array.isArray(item)) return item;
    const record = item as Record<string, unknown>;
    const rawTags = Array.isArray(record.misconceptionTags) ? record.misconceptionTags : [];
    let optionChanged = false;
    const tags: string[] = [];
    const seen = new Set<string>();
    for (const rawTag of rawTags) {
      const tag = String(rawTag ?? '').trim();
      if (!tag) continue;
      const nextTag = sourceTags.has(normalizeTag(tag)) ? targetLabel : tag;
      if (nextTag !== tag) optionChanged = true;
      const key = normalizeTag(nextTag);
      if (seen.has(key)) {
        optionChanged = true;
        continue;
      }
      seen.add(key);
      tags.push(nextTag);
    }
    if (!optionChanged) return item;
    changed = true;
    changedOptions += 1;
    return { ...record, misconceptionTags: tags };
  });
  return { optionMetadata, changed, changedOptions };
}

function questionCandidateFromRow(row: QuestionRow): GeneratedQuestionCandidate {
  const generation = recordFrom(row.generationMetadata) ?? {};
  const localizations = recordFrom(generation.localizations) as GeneratedQuestionCandidate['localizations'] | null;
  return {
    subject: row.subject,
    topicId: row.topicId,
    blueprintId: row.blueprintId ?? 0,
    sourceType: 'ai',
    designedDifficulty: row.designedDifficulty,
    questionType: row.questionType,
    prompt: row.prompt,
    options: row.options as Array<{ id: string; text: string }>,
    correctAnswer: row.correctAnswer,
    explanation: row.explanation,
    knowledgeTags: Array.isArray(row.knowledgeTags) ? row.knowledgeTags as string[] : [],
    optionMetadata: Array.isArray(row.optionMetadata)
      ? row.optionMetadata as Array<{ optionId: string; distractorIntent?: string; misconceptionTags?: string[] }>
      : [],
    localizations: localizations ?? undefined,
    syllabusVersion: row.syllabusVersion
  };
}

function generationMetadataHasSmokeSignal(generation: Record<string, unknown>) {
  const scope = recordFrom(generation.syllabusScope) ?? {};
  const values = [
    generation.syllabusVersion,
    generation.generationMode,
    generation.generationSource,
    generation.sourceKind,
    scope.syllabusVersion,
    scope.topicCode,
    scope.topicTitle,
    scope.topicModule,
    scope.examScope
  ];
  return values.some((value) => cleanString(value).toLowerCase().includes('smoke'));
}

function generationPromptText(generation: Record<string, unknown>) {
  const localizations = recordFrom(generation.localizations) ?? {};
  const zh = recordFrom(localizations.zh) ?? {};
  const en = recordFrom(localizations.en) ?? {};
  return cleanString(zh.prompt) || cleanString(en.prompt);
}

function generationPromptLooksTrivialArithmetic(generation: Record<string, unknown>) {
  const prompt = generationPromptText(generation);
  if (!prompt || prompt.length > 80) return false;
  const asksForValue = /(表达式|计算|求|值|多少|calculate|value|evaluate)/i.test(prompt);
  const hasArithmeticExpression = /\d+\s*(?:[+＋\-−*×xX÷/])\s*\d+(?:\s*(?:[+＋\-−*×xX÷/])\s*\d+)?/.test(prompt);
  const hasAdvancedSignal = /(函数|方程|不等式|概率|统计|几何|向量|导数|积分|矩阵|证明|推理|建模|参数|集合|实数|分布|function|equation|probability|geometry|vector|derivative|integral|matrix|model)/i.test(prompt);
  return asksForValue && hasArithmeticExpression && !hasAdvancedSignal;
}

export function subjectPracticeVerifiedBasicDerivativeShadowAllowsArithmeticShape(generationMetadata: unknown) {
  const generation = recordFrom(generationMetadata) ?? {};
  const scope = recordFrom(generation.scope) ?? {};
  const targetProfile = recordFrom(generation.targetProfile) ?? {};
  const questionPlan = recordFrom(generation.questionPlan) ?? {};
  const renderConstraints = recordFrom(questionPlan.renderConstraints) ?? {};
  const questionPlanGate = recordFrom(generation.questionPlanGate) ?? {};
  const planValidation = recordFrom(questionPlanGate.validation) ?? {};
  const adherence = recordFrom(generation.questionPlanAdherence) ?? {};
  const formalVerification = recordFrom(generation.formalVerificationBundle) ?? {};
  const localShadowGeneration = recordFrom(generation.localShadowGeneration) ?? {};
  const sourceIsolationEvidence = recordFrom(generation.sourceIsolationEvidence) ?? {};
  const prompt = generationPromptText(generation);
  const exactScopeId = 'math-basic-derivative-v1:direct_polynomial_value';
  const sourceKind = cleanString(generation.sourceKind ?? generation.generationSource);
  const sourceBoundarySatisfied = sourceKind === 'syllabus'
    || (sourceKind === 'syllabus_and_past_paper_profile'
      && cleanString(sourceIsolationEvidence.status) === 'enforced_structural_projection'
      && cleanString(sourceIsolationEvidence.policyVersion) === 'question-generator-source-isolation-v3'
      && sourceIsolationEvidence.sourceIdentityOmitted === true
      && sourceIsolationEvidence.reversibleSourceFieldsOmitted === true
      && sourceIsolationEvidence.originalQuestionContentOmitted === true
      && Number(sourceIsolationEvidence.knownSourceLeakMatchCount) === 0);
  const exactDirectDerivativePrompt = /(?:f\s*\(\s*x\s*\)\s*=).{1,90}(?:x\s*(?:\^\s*[23]|[²³])|x).{0,40}f\s*['′]\s*[（(]\s*-?\d+\s*[)）]/i.test(prompt);
  const forbiddenAdvancedShape = /(切线|斜率|法线|单调|递增|递减|极值|最值|区间|参数|范围|存在|恒成立|分段|定义域|不可导|链式|复合|隐函数|高阶|sin|cos|tan|ln|log|sqrt|根式|根号|tangent|slope|normal line|monotonic|extremum|interval|parameter|range|piecewise|domain|chain rule|implicit|higher derivative)/i.test(prompt);
  return generationIntendedUse(generation) === 'subject_practice'
    && cleanString(generation.workClass) === SUBJECT_PRACTICE_OBSERVATION_WORK_CLASS
    && generation.suppressStudentPublication === true
    && cleanString(scope.subject).toLowerCase() === 'math'
    && cleanString(scope.intendedUse) === 'subject_practice'
    && cleanString(scope.targetUseCase) === 'subject_practice'
    && Number(generation.productionCellId) === 10
    && Number(generation.productionRunId) > 0
    && sourceBoundarySatisfied
    && normalizeDifficultyKey(targetProfile.difficultyBand ?? targetProfile.difficulty) === 'basic'
    && cleanString(questionPlan.schemaVersion) === 'subject-practice-question-plan-v1'
    && cleanString(questionPlan.policyVersion) === 'subject-practice-question-plan-policy-v1'
    && cleanString(questionPlan.subject).toLowerCase() === 'math'
    && cleanString(questionPlan.targetDifficulty).toLowerCase() === 'basic'
    && cleanString(questionPlan.taskFamily) === 'derivative_direct_evaluation'
    && cleanString(questionPlan.planTemplate) === 'math_derivative_condition_chain_v1'
    && cleanString(renderConstraints.exactDerivativeScope) === 'direct_polynomial_value'
    && renderConstraints.forbidBasicDerivativeComplexity === true
    && renderConstraints.forbidBasicDerivativeDomainTrap === true
    && Number(renderConstraints.maxBasicDerivativeReasoningMoves) === 1
    && cleanString(questionPlanGate.mode) === 'plan_required'
    && questionPlanGate.generationAllowed === true
    && planValidation.valid === true
    && adherence.adheres === true
    && cleanString(formalVerification.status) === 'verified'
    && cleanString(formalVerification.subject).toLowerCase() === 'math'
    && cleanString(formalVerification.taskFamily) === 'derivative_direct_evaluation'
    && cleanString(formalVerification.planTemplate) === 'math_derivative_condition_chain_v1'
    && cleanString(formalVerification.scopeId) === exactScopeId
    && cleanString(formalVerification.plannedScopeId) === exactScopeId
    && cleanString(formalVerification.oracleScopeId) === exactScopeId
    && formalVerification.scopeMatchedAcrossVerifiers === true
    && formalVerification.eligibleForProductionShadowObservation === true
    && cleanString(localShadowGeneration.generatorVersion) === SUBJECT_PRACTICE_MATH_DERIVATIVE_LOCAL_GENERATOR_VERSION
    && cleanString(localShadowGeneration.status) === 'generated_and_triple_verified'
    && cleanString(localShadowGeneration.scopeId) === exactScopeId
    && Number(localShadowGeneration.providerCallCount) === 0
    && Number(localShadowGeneration.estimatedCostUsd) === 0
    && localShadowGeneration.publicationSuppressed === true
    && exactDirectDerivativePrompt
    && prompt.length <= 140
    && !forbiddenAdvancedShape;
}

