function generationHasCompleteBilingualLocalization(generation: Record<string, unknown>) {
  const localizations = recordFrom(generation.localizations);
  const zh = recordFrom(localizations?.zh);
  const en = recordFrom(localizations?.en);
  const normalizedLocalizationOptions = (value: unknown) => {
    if (!Array.isArray(value)) return [];
    return value
      .map((item) => {
        const option = recordFrom(item);
        return {
          id: cleanString(option?.id).toUpperCase(),
          text: cleanString(option?.text)
        };
      })
      .filter((option) => /^[A-D]$/.test(option.id) && option.text);
  };
  const zhOptions = normalizedLocalizationOptions(zh?.options);
  const enOptions = normalizedLocalizationOptions(en?.options);
  const zhOptionIds = zhOptions.map((option) => option.id).sort().join('');
  const enOptionIds = enOptions.map((option) => option.id).sort().join('');
  return Boolean(
    cleanString(zh?.prompt) &&
    cleanString(zh?.explanation) &&
    cleanString(en?.prompt) &&
    cleanString(en?.explanation) &&
    zhOptions.length === 4 &&
    enOptions.length === 4 &&
    zhOptionIds === 'ABCD' &&
    enOptionIds === 'ABCD'
  );
}

function mathOptionTextsFromUnknown(value: unknown) {
  if (!Array.isArray(value)) return [];
  return value
    .map((item) => cleanString(recordFrom(item)?.text ?? item))
    .filter(Boolean);
}

function collectQuestionMathTexts(question: Pick<QuestionRow, 'prompt' | 'options' | 'explanation' | 'generationMetadata'>) {
  const generation = recordFrom(question.generationMetadata) ?? {};
  const localizations = recordFrom(generation.localizations) ?? {};
  const zh = recordFrom(localizations.zh) ?? {};
  const en = recordFrom(localizations.en) ?? {};
  const optionTexts = mathOptionTextsFromUnknown(question.options);
  const localizedOptionTexts = [
    ...mathOptionTextsFromUnknown(zh.options),
    ...mathOptionTextsFromUnknown(en.options)
  ];
  return [
    question.prompt,
    question.explanation,
    ...optionTexts,
    zh.prompt,
    zh.explanation,
    en.prompt,
    en.explanation,
    ...localizedOptionTexts
  ].map((value) => cleanString(value)).filter(Boolean);
}

function latexCommandGroupEnd(input: string, start: number) {
  let index = start;
  while (/\s/.test(input[index] ?? '')) index += 1;
  if (input[index] !== '{') return -1;
  let depth = 0;
  for (let cursor = index; cursor < input.length; cursor += 1) {
    const char = input[cursor];
    const escaped = cursor > 0 && input[cursor - 1] === '\\';
    if (char === '{' && !escaped) depth += 1;
    if (char === '}' && !escaped) depth -= 1;
    if (depth === 0) return cursor + 1;
  }
  return -1;
}

function hasBalancedLatexDelimiters(input: string) {
  let braceDepth = 0;
  let dollarCount = 0;
  for (let index = 0; index < input.length; index += 1) {
    const char = input[index];
    const escaped = index > 0 && input[index - 1] === '\\';
    if (char === '{' && !escaped) braceDepth += 1;
    if (char === '}' && !escaped) braceDepth -= 1;
    if (braceDepth < 0) return false;
    if (char === '$' && !escaped) dollarCount += 1;
  }
  return braceDepth === 0 && dollarCount % 2 === 0;
}

function delimitedLatexSegments(input: string) {
  const segments: string[] = [];
  const tokenPattern = /(\$\$[\s\S]+?\$\$|\$[^$\n]+?\$|\\\[[\s\S]+?\\\]|\\\([\s\S]+?\\\))/g;
  for (const match of input.matchAll(tokenPattern)) {
    const token = match[0];
    const body = token.startsWith('$$') || token.startsWith('\\[') || token.startsWith('\\(')
      ? token.slice(2, -2)
      : token.slice(1, -1);
    if (body.trim()) segments.push(body.trim());
  }
  return segments;
}

function mathTextIssueReasons(value: string) {
  const reasons: string[] = [];
  if (!value) return reasons;
  const hasMathSignal = /\\(?:frac|dfrac|sqrt|leq|geq|cdot|times|pm|infty|left|right|sin|cos|tan|log|ln|alpha|beta|theta|pi|Delta|sum|lim|cup|cap|neq|approx|parallel|perp|angle)\b|[_^]\s*\{|\$/.test(value);
  if (!hasMathSignal) return reasons;
  if (!hasBalancedLatexDelimiters(value)) reasons.push('math_latex_unbalanced_delimiters');
  for (const segment of delimitedLatexSegments(value)) {
    if (/[\u3400-\u9fff]/.test(segment) && !/\\(?:text|mathrm)\s*\{/.test(segment)) reasons.push('math_latex_cjk_in_formula');
  }
  for (const match of value.matchAll(/\\(?:d?frac)\b/g)) {
    const numeratorEnd = latexCommandGroupEnd(value, match.index + match[0].length);
    const denominatorEnd = numeratorEnd > 0 ? latexCommandGroupEnd(value, numeratorEnd) : -1;
    if (numeratorEnd < 0 || denominatorEnd < 0) reasons.push('math_latex_invalid_fraction');
  }
  for (const match of value.matchAll(/\\sqrt\b/g)) {
    let cursor = match.index + match[0].length;
    while (/\s/.test(value[cursor] ?? '')) cursor += 1;
    if (value[cursor] === '[') {
      const close = value.indexOf(']', cursor + 1);
      cursor = close >= 0 ? close + 1 : -1;
    }
    const radicandEnd = cursor >= 0 ? latexCommandGroupEnd(value, cursor) : -1;
    if (radicandEnd < 0) reasons.push('math_latex_invalid_sqrt');
  }
  if (/\\left\b/.test(value) !== /\\right\b/.test(value)) reasons.push('math_latex_unpaired_left_right');
  return Array.from(new Set(reasons));
}

