function isPureStatisticsVarianceLinearTransformCandidate(question: Pick<QuestionRow, 'prompt' | 'generationMetadata'>) {
  const generation = recordFrom(question.generationMetadata) ?? {};
  const targetProfile = recordFrom(generation.targetProfile) ?? {};
  const scope = recordFrom(generation.scope) ?? {};
  const topicText = [
    generation.topicTitle,
    generation.topic,
    scope.topicTitle,
    scope.topic,
    targetProfile.topicTitle,
    targetProfile.gapKey
  ].map((value) => cleanString(value)).join(' ');
  const promptText = questionPromptText(question).replace(/\s+/g, ' ');
  const isStatisticsTopic = /数据的数字特征|统计|statistics|data/i.test(topicText)
    || /方差|平均数|均值|标准差|中位数|极差|variance|mean|standard deviation/i.test(promptText);
  if (!isStatisticsTopic || !/方差|variance/i.test(promptText)) return false;
  const hasIndexedDataFamily = /x\s*[₁-₉0-9_i，,\s…\.]{3,}x/i.test(promptText)
    || /x1\s*[,，、]\s*x2.{0,12}x10/i.test(promptText)
    || /x_?1\s*[,，、]\s*x_?2.{0,12}x_?10/i.test(promptText);
  const hasKnownMeanOrVariance = /(均值|平均数|方差|variance|mean).{0,18}(为|=)\s*[-+]?\d/i.test(promptText);
  const hasLinearTransform = /(每个|各|所有)?数据(?:都|均|分别)?.{0,16}(乘以|乘|×|\*).{0,16}(再|然后)?(加上|加|减去|减|\+|-)/.test(promptText)
    || /(?:新数据|所得数据|y|yi|y_i|yᵢ)\s*=\s*[0-9a-z]*x(?:i|_i|ᵢ)?\s*[+＋-]\s*\d/i.test(promptText)
    || /(?:2x|3x|kx|ax)(?:i|_i|ᵢ)?\s*[+＋-]\s*\d/i.test(promptText);
  const asksNewVariance = /(新数据|所得数据|变换后|新样本|new data|transformed).{0,24}(方差|variance)|(?:求|计算|find|calculate).{0,24}(方差|variance)/i.test(promptText);
  const hasMeaningfulAlternativeStructure = /缺失|未知|待定|中位数|极差|标准差|比较|两组|甲|乙|频数|频率|分组|权重|样本容量|删去|去掉|替换|解释|判断/i.test(promptText);
  const pureKnownStatisticTransform = hasKnownMeanOrVariance && hasIndexedDataFamily && hasLinearTransform && asksNewVariance;
  return (pureKnownStatisticTransform || (hasLinearTransform && asksNewVariance)) && !hasMeaningfulAlternativeStructure;
}

function subjectPracticeTargetProfileIsStatistics(value: unknown) {
  const profile = recordFrom(value) ?? {};
  const text = [
    profile.gapKey,
    profile.topicTitle,
    profile.topicCode,
    profile.questionForm,
    profile.cognitiveSkill,
    profile.reason
  ].map((item) => cleanString(item)).join(' ');
  return /数据的数字特征|统计|statistics|data|variance|方差|均值|平均数|标准差/i.test(text);
}

function isTrivialStatisticsRawListCandidate(question: Pick<QuestionRow, 'prompt' | 'generationMetadata'>) {
  const generation = recordFrom(question.generationMetadata) ?? {};
  const targetProfile = recordFrom(generation.targetProfile) ?? {};
  const scope = recordFrom(generation.scope) ?? {};
  const topicText = [
    generation.topicTitle,
    generation.topic,
    scope.topicTitle,
    scope.topic,
    targetProfile.topicTitle,
    targetProfile.gapKey
  ].map((value) => cleanString(value)).join(' ');
  const promptText = questionPromptText(question).replace(/\s+/g, ' ');
  const isStatisticsTopic = /数据的数字特征|统计|statistics|data/i.test(topicText)
    || /方差|平均数|均值|标准差|中位数|极差|variance|mean|standard deviation/i.test(promptText);
  if (!isStatisticsTopic) return false;
  const asksDirectStatistic = /(?:求|计算|find|calculate).{0,20}(方差|样本方差|平均数|均值|标准差|极差|variance|mean|standard deviation|range)/i.test(promptText);
  const hasShortRawList = /(?:\d+(?:\.\d+)?\s*[,，、]\s*){3,}\d+(?:\.\d+)?/.test(promptText);
  const hasAlternativeStructure = /缺失|未知|待定|x\s*=|设x|中位数.*极差|极差.*中位数|比较|两组|甲|乙|频数|频率|分组|权重|样本容量|删去|去掉|替换|加入|增加|减少|变化|前后|原来|现在|若.*则|如果.*则/i.test(promptText);
  return asksDirectStatistic && hasShortRawList && !hasAlternativeStructure;
}

function questionMathTextIssueReasons(question: Pick<QuestionRow, 'prompt' | 'options' | 'explanation' | 'generationMetadata'>) {
  const reasons = collectQuestionMathTexts(question).flatMap(mathTextIssueReasons);
  if (isPureStatisticsVarianceLinearTransformCandidate(question)) {
    reasons.push('statistics_linear_transform_template');
  }
  if (isTrivialStatisticsRawListCandidate(question)) {
    reasons.push('statistics_raw_list_template');
  }
  return Array.from(new Set(reasons));
}

