  private async subjectPracticeActiveRegenerateJobCount(value: unknown) {
    const jobIds = subjectPracticeRegenerateJobIds(value);
    if (jobIds.length === 0) return 0;
    const [row] = await this.prisma.$queryRaw<Array<{ count: number }>>(Prisma.sql`
      SELECT COUNT(*)::int AS "count"
      FROM "csca_ai_generation_jobs"
      WHERE "id" IN (${Prisma.join(jobIds)})
        AND "status" IN ('queued', 'running')
    `);
    return Number(row?.count ?? 0) || 0;
  }

  private async subjectPracticeActiveRegenerateJobIdsForQuestion(input: {
    questionId: number;
    productionRunId?: number | null;
    productionCellId?: number | null;
  }) {
    const questionId = Number(input.questionId);
    if (!Number.isInteger(questionId) || questionId <= 0) return [];
    const productionRunId = Number(input.productionRunId);
    const productionCellId = Number(input.productionCellId);
    const rows = await this.prisma.$queryRaw<Array<{ id: number }>>(Prisma.sql`
      SELECT "id"
      FROM "csca_ai_generation_jobs"
      WHERE "status" IN ('queued', 'running')
        AND "prompt_metadata"->>'previousQuestionId' = ${String(questionId)}
        AND (${Number.isInteger(productionRunId) && productionRunId > 0 ? String(productionRunId) : null}::text IS NULL
          OR "prompt_metadata"->>'productionRunId' = ${Number.isInteger(productionRunId) && productionRunId > 0 ? String(productionRunId) : null})
        AND (${Number.isInteger(productionCellId) && productionCellId > 0 ? String(productionCellId) : null}::text IS NULL
          OR "prompt_metadata"->>'productionCellId' = ${Number.isInteger(productionCellId) && productionCellId > 0 ? String(productionCellId) : null})
      ORDER BY "id" ASC
      LIMIT 20
    `);
    return rows
      .map((row) => Number(row.id))
      .filter((id) => Number.isInteger(id) && id > 0);
  }

  private async archiveDuplicateSubjectPracticeRegenerateJobs(productionRunId: number, input: { limit?: number } = {}) {
    const runId = Number(productionRunId);
    if (!Number.isInteger(runId) || runId <= 0) return 0;
    const limit = cleanPositiveInt(input.limit, 50, 1, 200);
    const archivedAt = new Date().toISOString();
    const rows = await this.prisma.$queryRaw<Array<{ id: number }>>(Prisma.sql`
      WITH ranked AS (
        SELECT
          job."id",
          ROW_NUMBER() OVER (
            PARTITION BY job."prompt_metadata"->>'productionRunId',
                         job."prompt_metadata"->>'productionCellId',
                         job."prompt_metadata"->>'previousQuestionId'
            ORDER BY
              CASE job."status" WHEN 'running' THEN 0 WHEN 'queued' THEN 1 ELSE 2 END ASC,
              NULLIF(job."prompt_metadata"->>'processingStartedAt', '')::timestamp DESC NULLS LAST,
              job."updated_at" DESC,
              job."id" DESC
          ) AS "rank"
        FROM "csca_ai_generation_jobs" job
        WHERE job."status" IN ('queued', 'running', 'failed')
          AND job."prompt_metadata"->>'productionRunId' = ${String(runId)}
          AND COALESCE(job."prompt_metadata"->>'previousQuestionId', '') <> ''
      ),
      duplicate_jobs AS (
        SELECT "id"
        FROM ranked
        WHERE "rank" > 1
        ORDER BY "id" ASC
        LIMIT ${limit}
      )
      UPDATE "csca_ai_generation_jobs" job
      SET "status" = 'archived',
          "prompt_metadata" = COALESCE(job."prompt_metadata", '{}'::jsonb) || ${jsonInput({
            archivedAt,
            archiveReason: 'duplicate_subject_practice_regenerate_job',
            archiveNote: 'one_active_regenerate_job_per_previous_question'
          })}::jsonb,
          "updated_at" = CURRENT_TIMESTAMP
      FROM duplicate_jobs
      WHERE job."id" = duplicate_jobs."id"
      RETURNING job."id"
    `);
    return rows.length;
  }

  private async subjectPracticeProductionCellActiveInFlightJobCount(productionRunId: number, productionCellId: number, excludeJobId?: number | null) {
    if (!Number.isInteger(productionRunId) || productionRunId <= 0 || !Number.isInteger(productionCellId) || productionCellId <= 0) {
      return 0;
    }
    const staleRunningBefore = new Date(Date.now() - GENERATION_JOB_SUBJECT_PRACTICE_STALE_RUNNING_MS);
    const excludedJobId = Number(excludeJobId);
    const [row] = await this.prisma.$queryRaw<Array<{ count: bigint | number }>>(Prisma.sql`
      SELECT COUNT(*) AS "count"
      FROM "csca_ai_generation_jobs"
      WHERE "prompt_metadata"->>'productionRunId' = ${String(productionRunId)}
        AND "prompt_metadata"->>'productionCellId' = ${String(productionCellId)}
        AND (${Number.isInteger(excludedJobId) && excludedJobId > 0 ? excludedJobId : null}::int IS NULL OR "id" <> ${Number.isInteger(excludedJobId) && excludedJobId > 0 ? excludedJobId : null})
        AND (
          "status" = 'queued'
          OR ("status" = 'running' AND COALESCE(NULLIF("prompt_metadata"->>'processingStartedAt', '')::timestamp, "created_at") >= ${staleRunningBefore})
        )
    `);
    return Number(row?.count ?? 0);
  }

